-- =============================================================================
-- 483 — LE CAHIER D'EXERCICES DE 4E (partie 2)
--
-- FICHIER GÉNÉRÉ par scripts/exercices-sql.ts depuis contenu/exercices/4e/ :
-- ne pas l'éditer à la main, corriger le JSON et régénérer :
--   node node_modules/jiti/lib/jiti-cli.mjs scripts/exercices-sql.ts --num 483 --niveau 4e --fichiers anglais.jumelles,arts-plastiques.jumelles --suffixe 2 > supabase/contenu/483_exercices_4e_2.sql
--
-- 96 exercices écrits et relus : pour chaque chapitre, trois exercices faits
-- comme une page de manuel (★ facile, ★★ moyen, ★★★ plus corsé), avec leurs
-- documents (cartes, graphiques, textes, schémas…) et leurs questions. Le
-- contenu public va dans `exercices`, les réponses et explications dans
-- `exercices_cles` (qu'aucun élève ne lit). Gemmes et XP selon les étoiles
-- (5/10/15 gemmes, 20/35/50 XP), réglables ensuite en base.
--
--   anglais.jumelles        87 exercices · 29 chapitres
--   arts-plastiques.jumelles   9 exercices · 3 chapitres
--
-- L'identifiant d'un exercice est dérivé de (chapitre, position) : rejouer ce
-- fichier met les exercices à jour sans doublon, et garde les résultats des
-- élèves. Un exercice dont le chapitre n'existe pas en base est sauté.
--
-- PRÉREQUIS : 372 (le cahier). Idempotent. À exécuter à la main dans :
-- Supabase Dashboard → SQL Editor → New query → Run.
-- =============================================================================

DROP TABLE IF EXISTS pg_temp.exercices_seed;
CREATE TEMP TABLE exercices_seed AS
SELECT md5('exercice:' || v.chapter_id::text || ':' || v.position::text)::uuid AS id, v.*
FROM (VALUES
  ('10538146-2231-5db0-9bad-3d16034489c2'::uuid, 1, 1, 5, 20, 3,
   $ex${"titre":"Fatiguée tous les matins","competence":"comprendre-langue","situation":"Dans le journal du collège, Lola écrit à la rubrique « Conseils » : elle est toujours fatiguée le matin. Le journal lui répond.","documents":[{"id":"rubrique","type":"texte","genre":"article","titre":"Ask Dr Sam","blocs":["Dear Dr Sam, I’m tired every morning. What can I do? — Lola","Dear Lola, You should go to bed earlier. You shouldn’t use your phone at night. And you should drink some water in the morning."],"source":"Rubrique écrite pour l’exercice"}],"questions":[{"enonce":"Touche **tous les modaux** qui donnent un conseil à Lola.","aide":"Il y en a trois, dont un négatif.","type":"zone","document":"rubrique","multiple":true},{"enonce":"Remets en ordre : « Tu devrais réviser pour le contrôle ». La phrase commence par You.","aide":"Après *should*, le verbe reste à la base verbale.","type":"ordre","items":[{"id":"a","texte":"the"},{"id":"b","texte":"test"},{"id":"c","texte":"You"},{"id":"d","texte":"revise"},{"id":"e","texte":"for"},{"id":"f","texte":"should"}]},{"enonce":"Complète pour déconseiller de manger si tard.","aide":"On déconseille, donc c’est négatif.","type":"trous","segments":["You ",0," eat so late. It’s bad for your sleep."],"banque":["can","should","shouldn’t","to"]}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"zone","ids":["m15","m21","m29"]},"explication":"**should, shouldn’t, should** : *should* donne un conseil, *shouldn’t* le déconseille."},{"cle":{"type":"ordre","ids":["c","f","d","e","a","b"]},"explication":"**You should revise for the test** : should + verbe, sans *to*."},{"cle":{"type":"trous","trous":[["shouldn t"]]},"affichage":"shouldn’t","explication":"**shouldn’t** : la négation de *should* déconseille."}]$ex$::jsonb),
  ('10538146-2231-5db0-9bad-3d16034489c2'::uuid, 2, 2, 10, 35, 4,
   $ex${"titre":"Les devoirs oubliés","competence":"manier-langue","situation":"Tim a oublié ses devoirs à la maison et il s’inquiète. Sa copine Mia lui répond par messages.","documents":[{"id":"msg","type":"dialogue","modele":"sms","titre":"Messages de Tim et Mia","participants":[{"nom":"Tim","emoji":"👦","cote":"gauche"},{"nom":"Mia","emoji":"👧","cote":"droite"}],"repliques":[{"qui":"Tim","texte":"I forgot my homework! I’m in trouble!"},{"qui":"Mia","texte":"You should have checked your bag. You’d better call your teacher now, or she’ll be angry."}],"source":"Messages écrits pour l’exercice"}],"questions":[{"enonce":"Touche les **deux mots** qui disent ce que Tim **aurait dû faire** et n’a pas fait.","aide":"Cherche *should* suivi de *have*.","type":"zone","document":"msg","multiple":true},{"enonce":"Associe chaque phrase à son degré.","aide":"*Had better* sous-entend une menace.","type":"association","gauche":[{"id":"g0","texte":"You should rest."},{"id":"g1","texte":"You’d better rest."},{"id":"g2","texte":"You must rest."}],"droite":[{"id":"d0","texte":"Conseil ordinaire"},{"id":"d1","texte":"Obligation"},{"id":"d2","texte":"Conseil pressant"}]},{"enonce":"Tim s’excuse d’avoir dit une bêtise.","aide":"Il regrette une action passée.","type":"trous","segments":["I’m sorry. I ",0," have said that."],"banque":["to","don’t","shouldn’t","didn’t"]},{"enonce":"Quelle phrase donne un conseil pressant ?","aide":"*Had better* est suivi de la base verbale.","type":"choix","options":[{"id":"a","texte":"You’d better hurrying, or we’ll miss the train."},{"id":"b","texte":"You’d better hurried, or we’ll miss the train."},{"id":"c","texte":"You’d better hurry, or we’ll miss the train."},{"id":"d","texte":"You’d better to hurry, or we’ll miss the train."}],"multiple":false}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"zone","ids":["m8","m9"]},"explication":"**should have** + participe passé : un reproche ou un regret sur le passé."},{"cle":{"type":"association","paires":{"g0":"d0","g2":"d1","g1":"d2"}},"explication":"*Should* conseille, *had better* presse en menaçant un peu, *must* oblige."},{"cle":{"type":"trous","trous":[["shouldn t"]]},"affichage":"shouldn’t","explication":"**shouldn’t have** + participe passé : « je n’aurais pas dû »."},{"cle":{"type":"choix","ids":["c"]},"explication":"**You’d better hurry** : *had better* + base verbale, sans *to*."}]$ex$::jsonb),
  ('10538146-2231-5db0-9bad-3d16034489c2'::uuid, 3, 3, 15, 50, 5,
   $ex${"titre":"Un contrôle lundi","competence":"argumenter","situation":"Sam est inquiet pour son contrôle d’anglais de lundi. Il écrit à son amie Kim, qui lui répond.","documents":[{"id":"sam","type":"texte","genre":"lettre","titre":"L’e-mail de Sam","blocs":["Dear Kim, I’m nervous about my English test on Monday. I haven’t revised much and I played video games all weekend. What do you think I should do? — Sam"],"source":"E-mail écrit pour l’exercice"},{"id":"kim","type":"texte","genre":"lettre","titre":"La réponse de Kim","blocs":["Hi Sam, You should start now! You’d better not stay up too late, though. If I were you, I’d make a list of the verbs. Why don’t you ask Mr Brown for help? You should have started earlier, but it’s not too late."],"source":"E-mail écrit pour l’exercice"}],"questions":[{"enonce":"Touche les **trois mots** qui forment le conseil sous forme de **question**.","aide":"Cette tournure commence par *Why*.","type":"zone","document":"kim","multiple":true},{"enonce":"Quelle phrase de Kim est un **regret** sur le passé ?","aide":"Cherche *should* suivi de *have*.","type":"choix","options":[{"id":"a","texte":"If I were you, I’d make a list."},{"id":"b","texte":"You should have started earlier."},{"id":"c","texte":"Why don’t you ask Mr Brown?"},{"id":"d","texte":"You’d better not stay up too late."}],"multiple":false},{"enonce":"Sam regrette d’avoir joué tout le week-end.","aide":"Il n’aurait pas dû faire cela.","type":"trous","segments":["I ",0," have played so much."],"banque":["don’t","shouldn’t","didn’t","should"]},{"enonce":"Associe chaque tournure à son rôle.","aide":"Lis le rôle comme un coup de pouce.","type":"association","gauche":[{"id":"g0","texte":"Why don’t you…?"},{"id":"g1","texte":"If I were you, I’d…"},{"id":"g2","texte":"You should have…"},{"id":"g3","texte":"You’d better not…"}],"droite":[{"id":"d0","texte":"Conseil en question"},{"id":"d1","texte":"Conseil pressant négatif"},{"id":"d2","texte":"Reproche sur le passé"},{"id":"d3",