   $ex${"titre":"Une fête surprise","competence":"argumenter","situation":"Pour l’anniversaire de Tom, Ana et Zara organisent une surprise. Ana écrit un e-mail, Zara répond par message.","documents":[{"id":"ana","type":"texte","genre":"lettre","titre":"L’e-mail d’Ana","blocs":["Hi Zara, It’s Tom’s birthday on Saturday! Why don’t we organise a surprise party? We could meet at six at the park. Shall I buy the cake? Let’s not tell him!"],"source":"E-mail écrit pour l’exercice"},{"id":"zara","type":"dialogue","modele":"sms","titre":"Le message de Zara","participants":[{"nom":"Ana","emoji":"👧","cote":"gauche"},{"nom":"Zara","emoji":"👩","cote":"droite"}],"repliques":[{"qui":"Zara","texte":"Good idea! But I’d rather stay indoors because it will be cold. How about having it at my place instead?"}],"source":"Message écrit pour l’exercice"}],"questions":[{"enonce":"Touche les **deux mots** qui proposent de **ne pas** faire quelque chose.","aide":"Ils sont tout à la fin du message.","type":"zone","document":"ana","multiple":true},{"enonce":"Touche les **deux mots** qui disent la **préférence** de Zara.","aide":"Elle préférerait rester à l’intérieur.","type":"zone","document":"zara","multiple":true},{"enonce":"Quelle phrase compare deux préférences ?","aide":"On compare avec *than*.","type":"choix","options":[{"id":"a","texte":"I’d rather to stay indoors than going to the park."},{"id":"b","texte":"I’d rather stay indoors than go to the park."},{"id":"c","texte":"I’d rather stay indoors that go to the park."},{"id":"d","texte":"I’d rather staying indoors than go to the park."}],"multiple":false},{"enonce":"Associe chaque phrase à son rôle.","aide":"Pense à ce que dit celui qui parle.","type":"association","gauche":[{"id":"g0","texte":"I’d rather not."},{"id":"g1","texte":"That sounds great!"},{"id":"g2","texte":"Shall we start?"},{"id":"g3","texte":"Let’s go, shall we?"}],"droite":[{"id":"d0","texte":"Accepter"},{"id":"d1","texte":"Relancer en fin de phrase"},{"id":"d2","texte":"Refuser poliment"},{"id":"d3","texte":"Proposer"}]},{"enonce":"Remets en ordre : « Je préfère rester à l’intérieur plutôt que sortir ». La phrase commence par I’d.","aide":"*Than* sépare les deux préférences.","type":"ordre","items":[{"id":"a","texte":"I’d"},{"id":"b","texte":"out"},{"id":"c","texte":"go"},{"id":"d","texte":"stay"},{"id":"e","texte":"than"},{"id":"f","texte":"rather"},{"id":"g","texte":"indoors"}]}]}$ex$::jsonb,
