   $ex${"titre":"Eva et Sam parlent de sport","competence":"comprendre-langue","situation":"Eva interroge Sam sur son frère. Tous les deux parlent de sport.","documents":[{"id":"sport","type":"dialogue","modele":"sms","titre":"Messages d’Eva et Sam","participants":[{"nom":"Eva","emoji":"👧","cote":"gauche"},{"nom":"Sam","emoji":"👦","cote":"droite"}],"repliques":[{"qui":"Eva","texte":"Does your brother play football?"},{"qui":"Sam","texte":"No, he doesn’t. He plays tennis."},{"qui":"Eva","texte":"Do you play tennis too?"},{"qui":"Sam","texte":"Yes, I do."}],"source":"Messages écrits pour l’exercice"}],"questions":[{"enonce":"Touche les **deux auxiliaires** qui ouvrent les questions d’Eva.","aide":"Ils sont en début de phrase, avant le sujet.","type":"zone","document":"sport","multiple":true},{"enonce":"Touche le mot qui exprime la **négation** dans la réponse de Sam.","aide":"Il se termine par -n’t.","type":"zone","document":"sport","multiple":false},{"enonce":"Complète la phrase de Sam avec la bonne forme du verbe.","aide":"Après doesn’t, le verbe revient à sa base.","type":"trous","segments":["He doesn’t ",0," football."],"banque":["played","play","playing","plays"]}]}$ex$::jsonb,
