  ('f8094a53-d8ea-5e70-8797-cf6ca8188800'::uuid, 2, 2, 10, 35, 4,
   $ex${"titre":"Les erreurs du cahier","competence":"manier-langue","situation":"Une élève a recopié quatre phrases dans son cahier, mais trois contiennent une erreur de verbe. Aide-la à les corriger.","documents":[{"id":"cahier","type":"texte","genre":"consigne","titre":"Le cahier d’Inès","blocs":["1. She doesn’t works here.","2. Did you went to the cinema?","3. He didn’t played football.","4. What do you do?"],"source":"Phrases écrites pour l’exercice"}],"questions":[{"enonce":"Touche les **trois verbes fautifs**.","aide":"Après doesn’t, didn’t et did, le verbe doit être à la base.","type":"zone","document":"cahier","multiple":true},{"enonce":"Complète la phrase au passé.","aide":"La phrase est au passé, et le verbe go est à la base.","type":"trous","segments":["He ",0," go to school yesterday."],"banque":["don’t","doesn’t","didn’t","wasn’t"]},{"enonce":"Remets en ordre : « Qu’est-ce qu’elle fait dans la vie ? » La phrase commence par What.","aide":"Le premier do est l’auxiliaire, le second est le verbe.","type":"ordre","items":[{"id":"a","texte":"she"},{"id":"b","texte":"What"},{"id":"c","texte":"do"},{"id":"d","texte":"does"}]},{"enonce":"Range chaque question : demande-t-elle l’auxiliaire **do** ?","aide":"Pas de do avec be, avec un modal ou quand who est le sujet.","type":"categories","categories":[{"id":"c0","texte":"Avec do"},{"id":"c1","texte":"Sans do"}],"items":[{"id":"i0","texte":"Does she work here?"},{"id":"i1","texte":"What do you do?"},{"id":"i2","texte":"Did you go to school?"},{"id":"i3","texte":"Is she a teacher?"},{"id":"i4","texte":"Who broke the window?"},{"id":"i5","texte":"Can you swim?"}]}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"zone","ids":["m3","m8","m15"]},"explication":"**works, went, played** : do porte déjà la marque du temps et de la personne, le verbe reprend sa **base**."},{"cle":{"type":"trous","trous":[["didn t"]]},"affichage":"didn’t","explication":"**He didn’t go** : une seule marque de temps, portée par **didn’t**."},{"cle":{"type":"ordre","ids":["b","d","a","c"]},"explication":"**What does she do?** Auxiliaire *does*, sujet, verbe lexical *do*."},{"cle":{"type":"categories","items":{"i0":"c0","i1":"c0","i2":"c0","i3":"c1","i4":"c1","i5":"c1"}},"explication":"**Do** avec les verbes lexicaux ; **pas de do** avec be, can, ni quand *who* est sujet."}]$ex$::jsonb),
  ('f8094a53-d8ea-5e70-8797-cf6ca8188800'::uuid, 3, 3, 15, 50, 5,
   $ex${"titre":"Après le concert","competence":"argumenter","situation":"Nora interroge Ben sur le concert d’hier. Un tableau résume l’enquête menée dans la classe.","documents":[{"id":"concert","type":"dialogue","modele":"sms","titre":"Messages de Nora et Ben","participants":[{"nom":"Nora","emoji":"👧","cote":"gauche"},{"nom":"Ben","emoji":"👦","cote":"droite"}],"repliques":[{"qui":"Nora","texte":"Did you enjoy the concert?"},{"qui":"Ben","texte":"I did enjoy it! It was amazing."},{"qui":"Nora","texte":"Who bought the tickets?"},{"qui":"Ben","texte":"Mia did. She doesn’t like crowds, but she did come."}],"source":"Messages écrits pour l’exercice"},{"id":"enquete","type":"tableau","titre":"Concert survey","colonnes":["Question","Yes","No"],"lignes":[["Did you enjoy it?","18","2"],["Did you go by bus?","7","13"]],"source":"Chiffres inventés pour l’exercice"}],"questions":[{"enonce":"Touche les **deux fois** où *did* sert à **insister** (il est suivi d’un verbe).","aide":"Pas dans la question ni dans la reprise « Mia did. ».","type":"zone","document":"concert","multiple":true},{"enonce":"Pourquoi écrit-on « Who **bought** the tickets? » sans did ?","aide":"Pense à ce qui fait l’action.","type":"choix","options":[{"id":"a","texte":"Parce que bought est un verbe irrégulier"},{"id":"b","texte":"Parce que tickets est au pluriel"},{"id":"c","texte":"Parce que la question est au présent"},{"id":"d","texte":"Parce que who est le sujet de la question"}],"multiple":false},{"enonce":"Mia ne supporte pas la foule (présent). Complète.","aide":"Mia est à la 3e personne du singulier, au présent.","type":"trous","segments":["Mia ",0," like crowds."],"banque":["don’t","didn’t","doesn’t","isn’t"]},{"enonce":"Remets en ordre la question de Nora. La phrase commence par Did.","aide":"Auxiliaire, sujet, verbe à la base.","type":"ordre","items":[{"id":"a","texte":"the"},{"id":"b","texte":"Did"},{"id":"c","texte":"concert"},{"id":"d","texte":"you"},{"id":"e","texte":"enjoy"}]},{"enonce":"D’après le tableau, **combien d’élèves n’ont pas pris le bus** ?","aide":"Lis la colonne « No » de la ligne « Did you go by bus? ».","type":"nombre"}]}$ex$::jsonb,
