  ('f5f7556d-f213-588d-8721-a648eb9ff50a'::uuid, 3, 3, 15, 50, 6,
   $ex${"titre":"Le concert de la chorale","competence":"analyser-texte","situation":"La chorale du collège a donné un concert. Voici un compte rendu écrit par un élève et les consignes du prochain concert.","documents":[{"id":"compte","type":"texte","genre":"article","titre":"Review","blocs":["Last night, our school choir sang beautifully at the town hall. The singers walked quietly onto the stage. Tom hardly slept before the concert, because he worked hard all week. Lately he has been very nervous, but he sang well enough to win."],"source":"Compte rendu écrit pour l’exercice"},{"id":"consigne","type":"texte","genre":"consigne","titre":"Next concert","blocs":["Friday at 7 p.m. in the gym. Please sit quietly and switch off your phones."],"source":"Consigne écrite pour l’exercice"}],"questions":[{"enonce":"Touche l’adverbe qui veut dire **« à peine »**.","aide":"Il ressemble à *hard* mais ne veut pas dire « durement ».","type":"zone","document":"compte","multiple":false},{"enonce":"Touche l’adverbe de **manière** qui dit comment s’asseoir.","aide":"Il se termine par -ly.","type":"zone","document":"consigne","multiple":false},{"enonce":"Que veut dire « Lately he has been nervous » ?","aide":"*Lately* n’a rien à voir avec *late*.","type":"choix","options":[{"id":"a","texte":"Tardivement, il a été nerveux"},{"id":"b","texte":"Il est devenu très nerveux"},{"id":"c","texte":"Il a été nerveux jusqu’à tard"},{"id":"d","texte":"Récemment, il a été nerveux"}],"multiple":false},{"enonce":"Remets en ordre : « Il a chanté magnifiquement à l’école hier ». La phrase commence par He.","aide":"Manière, puis lieu, puis temps.","type":"ordre","items":[{"id":"a","texte":"school"},{"id":"b","texte":"He"},{"id":"c","texte":"yesterday"},{"id":"d","texte":"at"},{"id":"e","texte":"sang"},{"id":"f","texte":"beautifully"}]},{"enonce":"Tom est assez habile pour jouer.","aide":"*Enough* se place après l’adjectif.","type":"trous","segments":["He is skilful ",0," to play."],"banque":["very","quite","too","enough"]},{"enonce":"Associe chaque adjectif à son adverbe.","aide":"Certains adverbes ne changent pas.","type":"association","gauche":[{"id":"g0","texte":"good"},{"id":"g1","texte":"fast"},{"id":"g2","texte":"happy"},{"id":"g3","texte":"simple"}],"droite":[{"id":"d0","texte":"happily"},{"id":"d1","texte":"fast"},{"id":"d2","texte":"simply"},{"id":"d3","texte":"well"}]}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"zone","ids":["m19"]},"explication":"**hardly** : à peine. Attention : *hard* veut dire « dur » ou « durement »."},{"cle":{"type":"zone","ids":["m10"]},"explication":"**quietly** : adverbe de manière formé avec -ly."},{"cle":{"type":"choix","ids":["d"]},"explication":"**Récemment** : *lately* ne veut pas dire « tardivement »."},{"cle":{"type":"ordre","ids":["b","e","f","d","a","c"]},"explication":"**He sang beautifully at school yesterday** : manière → lieu → temps."},{"cle":{"type":"trous","trous":[["enough"]]},"affichage":"enough","explication":"**skilful enough** : *enough* suit l’adjectif."},{"cle":{"type":"association","paires":{"g2":"d0","g1":"d1","g3":"d2","g0":"d3"}},"explication":"*Good → well*, *fast → fast*, *happy → happily*, *simple → simply*."}]$ex$::jsonb),
