   $ex${"titre":"Une carte postale de la plage","competence":"manier-langue","situation":"Ella passe la journée à la plage avec sa famille. Elle envoie une carte postale à son ami Max.","documents":[{"id":"carte","type":"texte","genre":"lettre","titre":"Postcard","blocs":["Dear Max, We went to the beach to swim. I stopped playing volleyball because I was tired, then I stopped to buy an ice cream. Remember to bring your hat! Love, Ella"],"source":"Carte écrite pour l’exercice"}],"questions":[{"enonce":"Touche les **deux mots** qui disent **pourquoi** la famille est allée à la plage.","aide":"Cherche *to* suivi d’un verbe, juste après *the beach*.","type":"zone","document":"carte","multiple":true},{"enonce":"Que veut dire « I stopped to buy an ice cream » ?","aide":"*Stop to* indique le but de l’arrêt.","type":"choix","options":[{"id":"a","texte":"Je me suis arrêtée pour acheter une glace"},{"id":"b","texte":"J’ai cessé de m’arrêter dans les magasins"},{"id":"c","texte":"J’ai arrêté d’acheter des glaces pour de bon"},{"id":"d","texte":"Je me suis arrêtée d’en manger à la plage"}],"multiple":false},{"enonce":"Ella s’est arrêtée de jouer car elle était fatiguée.","aide":"Elle a cessé son activité.","type":"trous","segments":["I stopped ",0," volleyball: I was tired."],"banque":["play","played","playing","to play"]},{"enonce":"Remets en ordre : « J’ai hâte de te voir ». La phrase commence par I’m.","aide":"*Look forward to* est suivi d’un verbe en -ING.","type":"ordre","items":[{"id":"a","texte":"looking"},{"id":"b","texte":"I’m"},{"id":"c","texte":"seeing"},{"id":"d","texte":"to"},{"id":"e","texte":"you"},{"id":"f","texte":"forward"}]}]}$ex$::jsonb,
