  ('7ce0814d-a42a-5690-b319-93daf025c9a4'::uuid, 3, 3, 15, 50, 5,
   $ex${"titre":"Premières semaines dans un nouveau collège","competence":"argumenter","situation":"Nora vient d’arriver dans un nouveau collège. Elle écrit à une amie et consulte son planning de la semaine.","documents":[{"id":"nora","type":"texte","genre":"lettre","titre":"L’e-mail de Nora","blocs":["Hi Zoe, My new school is great. I managed to make friends quickly. I love playing football, but I can’t stand getting up early. Before leaving home, I always check my bag. I forgot to bring my lunch yesterday!"],"source":"E-mail écrit pour l’exercice"},{"id":"planning","type":"tableau","titre":"Le planning de Nora","colonnes":["Day","Activity","Why"],"lignes":[["Monday","Go to the library","to borrow books"],["Tuesday","Join the swimming club","to keep fit"],["Wednesday","Take a piano lesson","to learn new songs"]],"enteteLignes":true,"source":"Planning écrit pour l’exercice"}],"questions":[{"enonce":"Touche les **deux verbes** de l’e-mail qui sont suivis de **to + verbe**.","aide":"Ce sont des verbes de réussite et d’oubli.","type":"zone","document":"nora","multiple":true},{"enonce":"Que veut dire « I forgot to bring my lunch » ?","aide":"*Forget to* + verbe parle d’une action qu’on n’a pas faite.","type":"choix","options":[{"id":"a","texte":"Je me suis souvenue de l’apporter"},{"id":"b","texte":"J’ai refusé de l’apporter"},{"id":"c","texte":"J’ai oublié d’apporter mon déjeuner"},{"id":"d","texte":"J’ai oublié que j’avais apporté mon déjeuner"}],"multiple":false},{"enonce":"Nora va à la bibliothèque pour emprunter des livres.","aide":"Le but se dit avec l’infinitif.","type":"trous","segments":["On Monday, she goes to the library ",0," borrow books."],"banque":["borrowing","to","borrow","for"]},{"enonce":"Range chaque phrase selon qu’elle est correcte ou fautive.","aide":"Après une préposition ou *avoid* : -ING. Pour dire « pour », on utilise *to*.","type":"categories","categories":[{"id":"c0","texte":"Correcte"},{"id":"c1","texte":"Fautive"}],"items":[{"id":"i0","texte":"I went to the shop for buying bread."},{"id":"i1","texte":"He avoids to be late."},{"id":"i2","texte":"She is good at swimming."},{"id":"i3","texte":"I went to the shop to buy bread."},{"id":"i4","texte":"He avoids being late."},{"id":"i5","texte":"She is good at to swim."}]},{"enonce":"Touche la case qui donne l’activité de **mercredi**.","aide":"Repère la ligne de mercredi.","type":"zone","document":"planning","multiple":false}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"zone","ids":["m8","m33"]},"explication":"**managed to** et **forgot to** : ces verbes sont suivis de *to* + verbe."},{"cle":{"type":"choix","ids":["c"]},"explication":"**J’ai oublié d’apporter** : *forget to* + verbe."},{"cle":{"type":"trous","trous":[["to"]]},"affichage":"to","explication":"**to borrow** : l’infinitif de but répond à la question « pourquoi ? »."},{"cle":{"type":"categories","items":{"i0":"c1","i1":"c1","i2":"c0","i3":"c0","i4":"c0","i5":"c1"}},"explication":"*Good at* + -ING, *avoid* + -ING, but = *to* + verbe."},{"cle":{"type":"zone","ids":["r2c1"]},"explication":"**Take a piano lesson** : c’est l’activité du mercredi."}]$ex$::jsonb),
  ('70b2daa1-521a-56f0-94a1-37551fa6a65f'::uuid, 1, 1, 5, 20, 3,
