  ('70b2daa1-521a-56f0-94a1-37551fa6a65f'::uuid, 2, 2, 10, 35, 4,
   $ex${"titre":"Les services de la semaine","competence":"manier-langue","situation":"La famille de Maya a fait réparer et nettoyer plusieurs choses cette semaine. Voici le relevé des services.","documents":[{"id":"releve","type":"fiche","modele":"ticket","entete":"Home services","sousTitre":"Week 12","emoji":"🧾","lignes":[{"texte":"Hair cut","valeur":"£12","id":"z1"},{"texte":"Car wash","valeur":"£8","id":"z2"},{"texte":"Phone screen repair","valeur":"£45","id":"z3"},{"separateur":true},{"texte":"TOTAL","valeur":"£65","gras":true}],"pied":"Thank you!","teinte":"bleu","source":"Relevé écrit pour l’exercice"}],"questions":[{"enonce":"Touche la ligne qui correspond à « I had my phone repaired. »","aide":"Cherche ce qui concerne le téléphone.","type":"zone","document":"releve","multiple":false},{"enonce":"Range chaque phrase : l’a-t-on fait soi-même ou l’a-t-on fait faire ?","aide":"*Have* ou *get* + complément + participe passé = faire faire.","type":"categories","categories":[{"id":"c0","texte":"Fait soi-même"},{"id":"c1","texte":"Fait faire"}],"items":[{"id":"i0","texte":"She fixed her bike."},{"id":"i1","texte":"She got her phone fixed."},{"id":"i2","texte":"We had the car washed."},{"id":"i3","texte":"He painted the wall."},{"id":"i4","texte":"He had the wall painted."},{"id":"i5","texte":"I washed the car."}]},{"enonce":"La voiture a été lavée au garage.","aide":"Après *had the car*, on met le participe passé.","type":"trous","segments":["We had the car ",0," last Friday."],"banque":["to wash","washed","washing","wash"]},{"enonce":"Remets en ordre : « J’ai fait réparer mon vélo ». La phrase commence par I.","aide":"Le participe passé vient en dernier.","type":"ordre","items":[{"id":"a","texte":"my"},{"id":"b","texte":"had"},{"id":"c","texte":"bike"},{"id":"d","texte":"repaired"},{"id":"e","texte":"I"}]}]}$ex$::jsonb,
