  ('70b2daa1-521a-56f0-94a1-37551fa6a65f'::uuid, 3, 3, 15, 50, 5,
   $ex${"titre":"Une journée chez l’oncle coiffeur","competence":"argumenter","situation":"Sam a passé un samedi dans le salon de coiffure de son oncle. Il écrit un e-mail à sa grand-mère, puis discute avec son ami Luc.","documents":[{"id":"sam","type":"texte","genre":"lettre","titre":"L’e-mail de Sam","blocs":["Dear Gran, My uncle got me to help in his shop on Saturday. He made me sweep the floor all morning. I was made to wear a funny apron! Afterwards, I had my hair cut for free."],"source":"E-mail écrit pour l’exercice"},{"id":"luc","type":"dialogue","modele":"sms","titre":"Messages de Luc et Sam","participants":[{"nom":"Luc","emoji":"👦","cote":"gauche"},{"nom":"Sam","emoji":"🧑","cote":"droite"}],"repliques":[{"qui":"Luc","texte":"Did your uncle let you cut hair?"},{"qui":"Sam","texte":"No! He didn’t let me touch the scissors."}],"source":"Messages écrits pour l’exercice"}],"questions":[{"enonce":"Touche le mot qui montre le **passif** de *make*. Après lui, *to* réapparaît.","aide":"Cherche *I was … to wear*.","type":"zone","document":"sam","multiple":false},{"enonce":"Pourquoi écrit-on « I was made to wear » mais « He made me sweep » ?","aide":"Compare la voix active et la voix passive.","type":"choix","options":[{"id":"a","texte":"Parce que sweep est un verbe d’état"},{"id":"b","texte":"Parce que wear est irrégulier"},{"id":"c","texte":"Au passif, make est suivi de to"},{"id":"d","texte":"Parce que was est un modal"}],"multiple":false},{"enonce":"Complète pour dire « Il ne m’a pas laissé toucher les ciseaux ».","aide":"Il s’agit d’une permission refusée.","type":"trous","segments":["He didn’t ",0," me touch the scissors."],"banque":["make","get","have","let"]},{"enonce":"Associe chaque phrase française à sa traduction.","aide":"Choisis le verbe : obliger, faire faire, autoriser, convaincre.","type":"association","gauche":[{"id":"g0","texte":"Il m’a fait attendre."},{"id":"g1","texte":"Je me suis fait couper les cheveux."},{"id":"g2","texte":"Il m’a laissé sortir."},{"id":"g3","texte":"J’ai réussi à le convaincre de venir."}],"droite":[{"id":"d0","texte":"I had my hair cut."},{"id":"d1","texte":"He made me wait."},{"id":"d2","texte":"He let me go out."},{"id":"d3","texte":"I got him to come."}]},{"enonce":"Remets en ordre : « Mon oncle m’a convaincu de l’aider ». La phrase commence par My.","aide":"*Get* + complément + *to* + verbe.","type":"ordre","items":[{"id":"a","texte":"My"},{"id":"b","texte":"got"},{"id":"c","texte":"uncle"},{"id":"d","texte":"to"},{"id":"e","texte":"him"},{"id":"f","texte":"me"},{"id":"g","texte":"help"}]}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"zone","ids":["m23"]},"explication":"**made** : au passif, *make* est suivi de *to* (*I was made to wear*)."},{"cle":{"type":"choix","ids":["c"]},"explication":"**Au passif**, *make* est suivi de **to** + verbe."},{"cle":{"type":"trous","trous":[["let"]]},"affichage":"let","explication":"**let** : *let* + complément + base verbale = autoriser."},{"cle":{"type":"association","paires":{"g1":"d0","g0":"d1","g2":"d2","g3":"d3"}},"explication":"*Make* oblige, *have* fait faire, *let* autorise, *get … to* convainc."},{"cle":{"type":"ordre","ids":["a","c","b","f","d","g","e"]},"explication":"**My uncle got me to help him** : get + complément + to + verbe = convaincre."}]$ex$::jsonb),
  ('b2940b51-c270-5123-9227-06775f592602'::uuid, 1, 1, 5, 20, 3,
   $ex${"titre":"Une invitation à la pizzeria","competence":"comprendre-langue","situation":"Lily invite Tom à dîner à la pizzeria. Elle lui pose plusieurs questions par message.","documents":[{"id":"pizza","type":"dialogue","modele":"sms","titre":"Messages de Lily et Tom","participants":[{"nom":"Lily","emoji":"👧","cote":"gauche"},{"nom":"Tom","emoji":"👦","cote":"droite"}],"repliques":[{"qui":"Lily","texte":"Do you like pizza? Are you free tonight? Can you come at six?"},{"qui":"Tom","texte":"Yes, I do! I’m free, and I can come at six."}],"source":"Messages écrits pour l’exercice"}],"questions":[{"enonce":"Touche les **trois auxiliaires** qui ouvrent les questions de Lily.","aide":"Dans une question, l’auxiliaire se place devant le sujet *you*.","type":"zone","document":"pizza","multiple":true},{"enonce":"Dans la réponse « Yes, I **do** », à quoi sert *do* ?","aide":"Tom ne répète pas « like pizza ».","type":"choix","options":[{"id":"a","texte":"À poser une question, comme dans « Do you like it? »"},{"id":"b","texte":"À éviter de répéter le verbe like : c’est une reprise courte"},{"id":"c","texte":"À former un temps composé, comme dans « I have seen »"},{"id":"d","texte":"À former une négation, comme dans « I don’t know »"}],"multiple":false},{"enonce":"Remets en ordre : « Peux-tu venir à six heures ? » La phrase commence par Can.","aide":"L’auxiliaire se place devant le sujet.","type":"ordre","items":[{"id":"a","texte":"come"},{"id":"b","texte":"you"},{"id":"c","texte":"at"},{"id":"d","texte":"Can"},{"id":"e","texte":"six"}]}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"zone","ids":["m0","m4","m8"]},"explication":"**Do, Are, Can** : l’auxiliaire passe devant le sujet pour former la question."},{"cle":{"type":"choix","ids":["b"]},"explication":"**Yes, I do.** : l’auxiliaire permet la **reprise courte**, sans répéter le verbe lexical."},{"cle":{"type":"ordre","ids":["d","b","a","c","e"]},"explication":"**Can you come at six?** Auxiliaire, sujet, verbe lexical."}]$ex$::jsonb),
  ('b2940b51-c270-5123-9227-06775f592602'::uuid, 2, 2, 10, 35, 4,
   $ex${"titre":"Au club de sport","competence":"manier-langue","situation":"Jack et Nina se retrouvent au club de sport. Ils parlent de la sœur de Nina.","documents":[{"id":"club","type":"dialogue","modele":"sms","titre":"Messages de Jack et Nina","participants":[{"nom":"Jack","emoji":"👦","cote":"gauche"},{"nom":"Nina","emoji":"👧","cote":"droite"}],"repliques":[{"qui":"Jack","texte":"Does your sister play tennis?"},{"qui":"Nina","texte":"No, she doesn’t. But she can swim, and she is learning to dive."}],"source":"Messages écrits pour l’exercice"}],"questions":[{"enonce":"Touche les **quatre auxiliaires** de la conversation.","aide":"Les autres verbes (play, swim, learning) portent le sens.","type":"zone","document":"club","multiple":true},{"enonce":"Range chaque verbe : porte-t-il un **sens** (lexical) ou aide-t-il à **construire** la phrase (auxiliaire) ?","aide":"Un auxiliaire n’a pas de sens propre : il sert à former une question, une négation, un temps.","type":"categories","categories":[{"id":"c0","texte":"Verbe lexical"},{"id":"c1","texte":"Auxiliaire"}],"items":[{"id":"i0","texte":"believe"},{"id":"i1","texte":"will"},{"id":"i2","texte":"think"},{"id":"i3","texte":"must"},{"id":"i4","texte":"eat"},{"id":"i5","texte":"can"},{"id":"i6","texte":"run"}]},{"enonce":"Remets en ordre la négation de « He plays tennis ». La phrase commence par He.","aide":"La négation se construit avec do au présent, et le verbe revient à la base.","type":"ordre","items":[{"id":"a","texte":"He"},{"id":"b","texte":"play"},{"id":"c","texte":"doesn’t"},{"id":"d","texte":"tennis"}]},{"enonce":"Associe chaque auxiliaire à ce qu’il forme.","aide":"Chaque famille d’auxiliaires a sa fonction.","type":"association","gauche":[{"id":"g0","texte":"be"},{"id":"g1","texte":"have"},{"id":"g2","texte":"do"},{"id":"g3","texte":"can"}],"droite":[{"id":"d0","texte":"les temps composés"},{"id":"d1","texte":"la capacité (un modal)"},{"id":"d2","texte":"les formes en -ING et le passif"},{"id":"d3","texte":"la négation et la question aux temps simples"}]}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"zone","ids":["m0","m7","m10","m14"]},"explication":"**Does, doesn’t, can, is** sont des auxiliaires : ils forment la question, la négation ou les temps."},{"cle":{"type":"categories","items":{"i0":"c0","i1":"c1","i2":"c0","i3":"c1","i4":"c0","i5":"c1","i6":"c0"}},"explication":"**eat, think, believe, run** portent un sens ; **can, must, will** sont des modaux, donc des auxiliaires."},{"cle":{"type":"ordre","ids":["a","c","b","d"]},"explication":"**He doesn’t play tennis.** *Doesn’t* porte la marque de la 3e personne : play n’a plus de -s."},{"cle":{"type":"association","paires":{"g1":"d0","g3":"d1","g0":"d2","g2":"d3"}},"explication":"**be** → -ING et passif ; **have** → temps composés ; **do** → négation et question aux temps simples ; **can** est un modal."}]$ex$::jsonb),
  ('b2940b51-c270-5123-9227-06775f592602'::uuid, 3, 3, 15, 50, 5,
   $ex${"titre":"Les devoirs de Dan","competence":"analyser-document","situation":"Maya demande à Dan s’il a fini ses devoirs, puis elle l’invite au parc. Elle note ensuite les questions à poser dans un tableau.","documents":[{"id":"devoirs","type":"dialogue","modele":"sms","titre":"Messages de Maya et Dan","participants":[{"nom":"Maya","emoji":"👧","cote":"gauche"},{"nom":"Dan","emoji":"👦","cote":"droite"}],"repliques":[{"qui":"Maya","texte":"Dan, have you finished your homework?"},{"qui":"Dan","texte":"No, I haven’t. I have a lot of maths to do. And you?"},{"qui":"Maya","texte":"Yes, I have. Can you come to the park?"},{"qui":"Dan","texte":"I can’t. I don’t have my bike."}],"source":"Messages écrits pour l’exercice"},{"id":"questions","type":"tableau","titre":"Les questions de Maya","colonnes":["Affirmation","Question"],"lignes":[["You are ready.","Are you ready?"],["You have a bike.","?"],["You have finished.","?"]],"source":"Tableau écrit pour l’exercice"}],"questions":[{"enonce":"Dans le message de Dan, touche le « have » qui est un **verbe lexical** (il veut dire « avoir à faire »).","aide":"Un verbe lexical porte un sens ; ici, ce n’est pas un temps composé.","type":"zone","document":"devoirs","multiple":false},{"enonce":"Complète les deux questions du tableau.","aide":"Have lexical demande do ; have auxiliaire passe devant le sujet.","type":"trous","segments":["Question 2: ",0," you have a bike? Question 3: ",1," you finished?"],"banque":["Are","Can","Do","Have"]},{"enonce":"Dan dit : « I don’t have my bike. » Pourquoi « don’t » et pas « haven’t » ?","aide":"Souviens-toi : have lexical se nie avec do.","type":"choix","options":[{"id":"a","texte":"Parce que haven’t est une forme trop familière en anglais"},{"id":"b","texte":"Parce que don’t est la forme de la 3e personne"},{"id":"c","texte":"Parce que bike est un nom indénombrable en anglais"},{"id":"d","texte":"Parce que have est ici un verbe lexical : il lui faut do"}],"multiple":false},{"enonce":"Remets en ordre la question de Maya. La phrase commence par Have.","aide":"L’auxiliaire have passe devant le sujet.","type":"ordre","items":[{"id":"a","texte":"you"},{"id":"b","texte":"finished"},{"id":"c","texte":"Have"},{"id":"d","texte":"homework"},{"id":"e","texte":"your"}]},{"enonce":"Dan ne peut pas venir. Complète sa réponse courte.","aide":"On reprend l’auxiliaire de la question.","type":"trous","segments":["Can you come? — No, I ",0,"."],"banque":["isn’t","can’t","haven’t","don’t"]}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"zone","ids":["m10"]},"explication":"**I have a lot of maths to do** : *have* est lexical (il exprime l’idée d’avoir quelque chose), alors que dans *Have you finished?* il est auxiliaire."},{"cle":{"type":"trous","trous":[["do"],["have"]]},"affichage":"Do · Have","explication":"**Do you have a bike?** (have lexical → do) et **Have you finished?** (have auxiliaire → il passe devant le sujet)."},{"cle":{"type":"choix","ids":["d"]},"explication":"**Have lexical (posséder)** se construit avec **do** : *I don’t have…*."},{"cle":{"type":"ordre","ids":["c","a","b","e","d"]},"explication":"**Have you finished your homework?** Auxiliaire, sujet, participe passé."},{"cle":{"type":"trous","trous":[["can t"]]},"affichage":"can’t","explication":"**No, I can’t.** La reprise courte reprend l’auxiliaire de la question (ici can)."}]$ex$::jsonb),
  ('51fe4970-7c31-5a9b-a4a2-e7959550b343'::uuid, 1, 1, 5, 20, 3,
   $ex${"titre":"Leo se présente","competence":"comprendre-langue","situation":"Leo cherche un correspondant. Il écrit un petit message de présentation.","documents":[{"id":"profil","type":"texte","genre":"lettre","titre":"Hello!","blocs":["Hi! My name is Leo and I am 12 years old. I’m English.","I have a sister. My sister is nine. She is a very good swimmer."],"source":"Message écrit pour l’exercice"}],"questions":[{"enonce":"Touche le verbe que Leo emploie pour dire **son âge**.","aide":"Le français dit « j’ai », pas l’anglais.","type":"zone","document":"profil","multiple":false},{"enonce":"Complète avec le verbe qui convient.","aide":"Pour l’âge, on emploie be.","type":"trous","segments":["My sister ",0," nine."],"banque":["have","are","has","is"]},{"enonce":"Comment dit-on « J’ai soif » ?","aide":"Comme pour l’âge, l’anglais emploie be.","type":"choix","options":[{"id":"a","texte":"I have thirsty."},{"id":"b","texte":"I do thirsty."},{"id":"c","texte":"I have a thirst."},{"id":"d","texte":"I am thirsty."}],"multiple":false}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"zone","ids":["m7"]},"explication":"**I am 12** : pour l’âge, l’anglais emploie **be**, jamais *have*."},{"cle":{"type":"trous","trous":[["is"]]},"affichage":"is","explication":"**My sister is nine.** Age = verbe **be**."},{"cle":{"type":"choix","ids":["d"]},"explication":"**I am thirsty.** *Be* s’emploie là où le français dit « avoir » : l’âge, la faim, la soif, le froid…"}]$ex$::jsonb),
  ('51fe4970-7c31-5a9b-a4a2-e7959550b343'::uuid, 2, 2, 10, 35, 4,
   $ex${"titre":"Une carte postale du zoo","competence":"manier-langue","situation":"Max et sa famille ont passé la journée au zoo. Sa sœur envoie une carte postale à sa grand-mère.","documents":[{"id":"carte","type":"texte","genre":"lettre","titre":"Postcard","blocs":["Dear Gran,","We were at the zoo yesterday. It was sunny. Max was hungry, so he had two sandwiches.","I had an ice cream and my parents had a coffee. Love, Ruby"],"source":"Carte écrite pour l’exercice"}],"questions":[{"enonce":"Touche les **trois formes de be au prétérit** de la carte.","aide":"Elles commencent par w-.","type":"zone","document":"carte","multiple":true},{"enonce":"Range chaque forme selon le verbe dont elle vient.","aide":"Be : was, were, been. Have : have, has, had.","type":"categories","categories":[{"id":"c0","texte":"Forme de be"},{"id":"c1","texte":"Forme de have"}],"items":[{"id":"i0","texte":"been"},{"id":"i1","texte":"was"},{"id":"i2","texte":"were"},{"id":"i3","texte":"had"},{"id":"i4","texte":"have"},{"id":"i5","texte":"has"}]},{"enonce":"Associe chaque phrase française à sa traduction.","aide":"L’anglais emploie be là où le français dit « avoir ».","type":"association","gauche":[{"id":"g0","texte":"J’ai chaud."},{"id":"g1","texte":"Il a sept ans."},{"id":"g2","texte":"Nous avons soif."},{"id":"g3","texte":"Elles ont raison."}],"droite":[{"id":"d0","texte":"He is seven."},{"id":"d1","texte":"They are right."},{"id":"d2","texte":"I am hot."},{"id":"d3","texte":"We are thirsty."}]},{"enonce":"Comment interroge-t-on « She has breakfast at eight » (have d’action) ?","aide":"Have d’action se construit avec do.","type":"choix","options":[{"id":"a","texte":"Is she have breakfast at eight?"},{"id":"b","texte":"Have she breakfast at eight?"},{"id":"c","texte":"Has she got breakfast at eight?"},{"id":"d","texte":"Does she have breakfast at eight?"}],"multiple":false}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"zone","ids":["m3","m9","m12"]},"explication":"**were, was, was** : prétérit de **be** (was avec I, he, she, it ; were avec you, we, they)."},{"cle":{"type":"categories","items":{"i0":"c0","i1":"c0","i2":"c0","i3":"c1","i4":"c1","i5":"c1"}},"explication":"**was, were, been** viennent de be ; **has, had, have** viennent de have."},{"cle":{"type":"association","paires":{"g1":"d0","g3":"d1","g0":"d2","g2":"d3"}},"explication":"**be** pour la chaleur, l’âge, la soif, avoir raison : on ne dit pas *have* dans ces cas."},{"cle":{"type":"choix","ids":["d"]},"explication":"**Does she have breakfast at eight?** *Have breakfast* est une action : elle demande **do**."}]$ex$::jsonb),
  ('51fe4970-7c31-5a9b-a4a2-e7959550b343'::uuid, 3, 3, 15, 50, 5,
   $ex${"titre":"Des contractions à deviner","competence":"argumenter","situation":"Tom et Anna parlent de leur ami Ben. Les contractions « ’s » ne veulent pas toujours dire la même chose. Un tableau rappelle le prétérit de be et de have.","documents":[{"id":"ben","type":"dialogue","modele":"sms","titre":"Messages de Tom et Anna","participants":[{"nom":"Tom","emoji":"👦","cote":"gauche"},{"nom":"Anna","emoji":"👧","cote":"droite"}],"repliques":[{"qui":"Tom","texte":"Is Ben at home?"},{"qui":"Anna","texte":"No, he’s gone to the shop. He’s hungry."}],"source":"Messages écrits pour l’exercice"},{"id":"prete","type":"tableau","titre":"Be et have au prétérit","colonnes":["Sujet","be","have"],"lignes":[["I","was","had"],["you","?","had"],["she","was","?"]],"source":"Tableau écrit pour l’exercice"}],"questions":[{"enonce":"Range chaque phrase selon ce que représente la contraction ’s.","aide":"C’est ce qui suit qui tranche : un adjectif, un verbe en -ing ou un nom → is ; un participe passé → has.","type":"categories","categories":[{"id":"c0","texte":"’s = is"},{"id":"c1","texte":"’s = has"}],"items":[{"id":"i0","texte":"It’s been a long day."},{"id":"i1","texte":"It’s raining."},{"id":"i2","texte":"She’s a teacher."},{"id":"i3","texte":"He’s tired."},{"id":"i4","texte":"She’s got a new bike."},{"id":"i5","texte":"He’s finished his homework."}]},{"enonce":"Touche la contraction où **’s veut dire has**.","aide":"Regarde ce qui suit : gone est un participe passé.","type":"zone","document":"ben","multiple":false},{"enonce":"D’après le tableau, complète le prétérit.","aide":"Be au prétérit : was ou were ; have au prétérit : une seule forme.","type":"trous","segments":["You ",0," (be) at home. She ",1," (have) a bike."],"banque":["has","was","were","had"]},{"enonce":"Remets en ordre : « Nous étions au parc hier. » La phrase commence par We.","aide":"We prend were au prétérit.","type":"ordre","items":[{"id":"a","texte":"at"},{"id":"b","texte":"park"},{"id":"c","texte":"yesterday"},{"id":"d","texte":"the"},{"id":"e","texte":"were"},{"id":"f","texte":"We"}]},{"enonce":"Complète la question avec have got.","aide":"Avec have got, on n’emploie pas do.","type":"trous","segments":[0," you got a bike?"],"banque":["Does","Are","Do","Have"]}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"categories","items":{"i0":"c1","i1":"c0","i2":"c0","i3":"c0","i4":"c1","i5":"c1"}},"explication":"**is** devant un adjectif, un nom ou -ing ; **has** devant un participe passé (finished, got, been)."},{"cle":{"type":"zone","ids":["m5"]},"explication":"**he’s gone** = he **has** gone (temps composé). *He’s hungry* = he **is** hungry."},{"cle":{"type":"trous","trous":[["were"],["had"]]},"affichage":"were · had","explication":"**you were** (be au prétérit avec you) et **she had** (had pour toutes les personnes)."},{"cle":{"type":"ordre","ids":["f","e","a","d","b","c"]},"explication":"**We were at the park yesterday.** Be au prétérit avec we : were."},{"cle":{"type":"trous","trous":[["have"]]},"affichage":"Have","explication":"**Have you got a bike?** *Have got* se construit **sans do** (britannique)."}]$ex$::jsonb),
