   $ex${"titre":"Le gâteau d’anniversaire de Jade","competence":"manier-langue","situation":"Jade prépare son gâteau d’anniversaire. Elle note ce qu’il y a dans la cuisine, ingrédient par ingrédient.","documents":[{"id":"cuisine","type":"tableau","titre":"In the kitchen","colonnes":["Ingredient","Quantity"],"lignes":[["eggs","6"],["flour","a little"],["apples","a few"],["sugar","none"],["milk","a lot"]],"source":"Tableau écrit pour l’exercice"}],"questions":[{"enonce":"Touche les **deux ingrédients dénombrables** du tableau.","aide":"On peut en compter un, deux, trois… avec « a » ou un pluriel.","type":"zone","document":"cuisine","multiple":true},{"enonce":"Complète avec les quantifieurs de la liste.","aide":"Apples se compte, flour non.","type":"trous","segments":["There are ",0," apples and ",1," flour."],"banque":["a few","much","many","a little"]},{"enonce":"Range chaque quantifieur selon le nom qui le suit.","aide":"Many et few vont avec des noms que l’on compte ; much et little avec des noms que l’on mesure.","type":"categories","categories":[{"id":"c0","texte":"Avec un dénombrable"},{"id":"c1","texte":"Avec un indénombrable"}],"items":[{"id":"i0","texte":"many"},{"id":"i1","texte":"few"},{"id":"i2","texte":"a little"},{"id":"i3","texte":"little"},{"id":"i4","texte":"a few"},{"id":"i5","texte":"much"}]},{"enonce":"Jade dit : « There is little flour. » Que veut-elle dire ?","aide":"Sans « a », little est négatif.","type":"choix","options":[{"id":"a","texte":"Il y en a un peu, c’est suffisant"},{"id":"b","texte":"Il y en a beaucoup"},{"id":"c","texte":"Il n’y en a pas du tout"},{"id":"d","texte":"Il y en a trop peu"}],"multiple":false}]}$ex$::jsonb,
