  ('1e4179de-11a9-5684-b607-9ff05266463c'::uuid, 1, 1, 5, 20, 3,
   $ex${"titre":"Les projets du week-end","competence":"comprendre-langue","situation":"Ana et Ben parlent de leur samedi par messages. Chacun a des projets, mais pas de la même façon.","documents":[{"id":"sms","type":"dialogue","modele":"sms","titre":"Messages d’Ana et Ben","participants":[{"nom":"Ana","emoji":"👧","cote":"gauche"},{"nom":"Ben","emoji":"👦","cote":"droite"}],"repliques":[{"qui":"Ana","texte":"It’s Saturday tomorrow! What are you doing?"},{"qui":"Ben","texte":"I’m meeting Sam at the cinema at three."},{"qui":"Ana","texte":"Nice! I’m going to tidy my room in the morning."},{"qui":"Ben","texte":"Oh no! I’ll come and help you!"}],"source":"Messages écrits pour l’exercice"}],"questions":[{"enonce":"Touche la forme qui annonce une **décision prise sur le moment**.","aide":"Elle est très courte et se contracte avec le pronom.","type":"zone","document":"sms","multiple":false},{"enonce":"Range chaque phrase selon la façon d’envisager l’avenir.","aide":"Plus c’est préparé, plus on s’éloigne de will.","type":"categories","categories":[{"id":"c0","texte":"Rendez-vous organisé"},{"id":"c1","texte":"Intention déjà formée"},{"id":"c2","texte":"Décision immédiate"}],"items":[{"id":"i0","texte":"I’m going to tidy my room."},{"id":"i1","texte":"I’ll come and help you!"},{"id":"i2","texte":"I’m meeting Sam at the cinema at three."}]},{"enonce":"Pourquoi Ben dit-il « I’m meeting Sam at the cinema at three » ?","aide":"Regarde ce que Ben précise : où et quand.","type":"choix","options":[{"id":"a","texte":"Parce qu’il fait une promesse à Sam."},{"id":"b","texte":"Parce qu’il vient de décider de voir Sam."},{"id":"c","texte":"Parce que le rendez-vous est organisé."},{"id":"d","texte":"Parce que c’est un horaire officiel."}],"multiple":false}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"zone","ids":["m27"]},"explication":"**I’ll** (= *I will*) exprime une décision prise au moment de parler : Ben propose son aide sur-le-champ."},{"cle":{"type":"categories","items":{"i0":"c1","i1":"c2","i2":"c0"}},"explication":"**BE + -ING** pour un rendez-vous organisé, **be going to** pour une intention, **will** pour une décision prise à l’instant."},{"cle":{"type":"choix","ids":["c"]},"explication":"Le **présent en BE + -ING** exprime un **rendez-vous organisé**, avec lieu et heure."}]$ex$::jsonb),
  ('1e4179de-11a9-5684-b607-9ff05266463c'::uuid, 2, 2, 10, 35, 4,
   $ex${"titre":"Le train pour Oxford","competence":"lire-tableau","situation":"Léo et sa mère vont à Oxford en train. Ils regardent le tableau des horaires puis échangent quelques messages.","documents":[{"id":"gare","type":"tableau","titre":"Horaires de la gare","colonnes":["Destination","Leaves","Arrives"],"lignes":[["Bath","09.40","10.35"],["Bristol","10.05","11.00"],["Oxford","10.30","11.25"]],"enteteLignes":false,"source":"Horaires inventés pour l’exercice"},{"id":"sms","type":"dialogue","modele":"sms","titre":"Messages de Maman et Léo","participants":[{"nom":"Mum","emoji":"👩","cote":"gauche"},{"nom":"Leo","emoji":"👦","cote":"droite"}],"repliques":[{"qui":"Mum","texte":"The train leaves at 10.30, so we must hurry."},{"qui":"Leo","texte":"I’m meeting Jack at the station at ten, remember?"},{"qui":"Mum","texte":"I’m going to buy a sandwich first."},{"qui":"Leo","texte":"I’ll carry your bag!"}],"source":"Messages écrits pour l’exercice"}],"questions":[{"enonce":"Léo va à Oxford. Touche l’**heure de départ** de son train.","aide":"Trouve d’abord la ligne d’Oxford, puis la colonne *Leaves*.","type":"zone","document":"gare","multiple":false},{"enonce":"Complète avec la forme qui convient pour un **horaire officiel**.","aide":"Un horaire officiel se dit au présent simple.","type":"trous","segments":["The train to Bristol ",0," at 10.05."],"banque":["leave","leaves","will leave","is leaving"]},{"enonce":"Complète après la conjonction de temps.","aide":"Après *as soon as*, l’anglais emploie le présent.","type":"trous","segments":["I’ll call you as soon as the train ",0," in Oxford."],"banque":["arriving","arrives","will arrive","arrived"]},{"enonce":"Associe chaque phrase des messages à ce qu’elle exprime.","aide":"Demande-toi à quel point la chose est préparée.","type":"association","gauche":[{"id":"g0","texte":"The train leaves at 10.30."},{"id":"g1","texte":"I’m meeting Jack at ten."},{"id":"g2","texte":"I’m going to buy a sandwich."},{"id":"g3","texte":"I’ll carry your bag!"}],"droite":[{"id":"d0","texte":"horaire officiel"},{"id":"d1","texte":"intention"},{"id":"d2","texte":"rendez-vous organisé"},{"id":"d3","texte":"décision immédiate"}]}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"zone","ids":["r2c1"]},"explication":"Le train d’Oxford part à **10.30** : c’est la case de la ligne *Oxford*, colonne *Leaves*."},{"cle":{"type":"trous","trous":[["leaves"]]},"affichage":"leaves","explication":"**leaves** : on emploie le **présent simple** pour un horaire officiel."},{"cle":{"type":"trous","trous":[["arrives"]]},"affichage":"arrives","explication":"**arrives** : après *as soon as*, on emploie le **présent**, jamais *will*."},{"cle":{"type":"association","paires":{"g0":"d0","g2":"d1","g1":"d2","g3":"d3"}},"explication":"**Présent simple** pour l’horaire, **BE + -ING** pour le rendez-vous, **be going to** pour l’intention, **will** pour la décision immédiate."}]$ex$::jsonb),
  ('1e4179de-11a9-5684-b607-9ff05266463c'::uuid, 3, 3, 15, 50, 5,
   $ex${"titre":"Le camp de la classe","competence":"argumenter","situation":"La classe de Jade part en camp au pays de Galles. Elle lit l’avis de la prof et échange avec sa mère.","documents":[{"id":"avis","type":"texte","genre":"article","titre":"Camp notice","blocs":["Our class is going to visit Wales next month. The coach leaves at 7.30 on Monday.","Mrs Hart is meeting the parents at the gate at seven. As soon as we arrive, we will unpack. Before we go to bed, we will tell stories."],"source":"Avis écrit pour l’exercice"},{"id":"sms","type":"dialogue","modele":"sms","titre":"Messages de Jade et Maman","participants":[{"nom":"Jade","emoji":"👧","cote":"gauche"},{"nom":"Mum","emoji":"👩","cote":"droite"}],"repliques":[{"qui":"Jade","texte":"I was going to pack last night, but I fell asleep."},{"qui":"Mum","texte":"Don’t worry. I’ll help you now."},{"qui":"Jade","texte":"Thanks! It’s going to rain, so I’ll take my coat."}],"source":"Messages écrits pour l’exercice"}],"questions":[{"enonce":"Touche le verbe au **présent simple** qui donne un **horaire officiel**.","aide":"Cherche l’heure de départ du car.","type":"zone","document":"avis","multiple":false},{"enonce":"Pourquoi écrit-on « As soon as we arrive » et pas « As soon as we will arrive » ?","aide":"Regarde le temps du verbe après la conjonction de temps.","type":"choix","options":[{"id":"a","texte":"Parce que *will* est réservé aux promesses."},{"id":"b","texte":"Parce qu’après *as soon as*, on emploie le présent."},{"id":"c","texte":"Parce que *arrive* est un verbe irrégulier."},{"id":"d","texte":"Parce que le car part déjà."}],"multiple":false},{"enonce":"Dans les messages de Jade, range chaque phrase.","aide":"Chaque forme a son sens : passé, sur le moment, indice visible.","type":"categories","categories":[{"id":"c0","texte":"Intention passée (was going to)"},{"id":"c1","texte":"Décision immédiate (will)"},{"id":"c2","texte":"Prédiction fondée sur un indice (be going to)"}],"items":[{"id":"i0","texte":"It’s going to rain."},{"id":"i1","texte":"I was going to pack last night."},{"id":"i2","texte":"I’ll help you now."},{"id":"i3","texte":"I’ll take my coat."}]},{"enonce":"Remets en ordre : « Avant d’aller nous coucher, nous raconterons des histoires. » La phrase commence par Before.","aide":"Après *before*, on emploie le présent.","type":"ordre","items":[{"id":"a","texte":"go"},{"id":"b","texte":"to bed,"},{"id":"c","texte":"we will"},{"id":"d","texte":"Before"},{"id":"e","texte":"we"},{"id":"f","texte":"tell stories"}]},{"enonce":"Complète avec la forme qui convient.","aide":"Après la conjonction de temps, le présent.","type":"trous","segments":["As soon as the coach ",0,", Mrs Hart will call the parents."],"banque":["stops","stopped","is stopping","will stop"]}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"zone","ids":["m11"]},"explication":"**leaves** : le présent simple donne l’horaire officiel du car."},{"cle":{"type":"choix","ids":["b"]},"explication":"Après **as soon as**, **when**, **before**, **after** et **until**, l’anglais emploie le **présent**, pas *will*."},{"cle":{"type":"categories","items":{"i0":"c2","i1":"c0","i2":"c1","i3":"c1"}},"explication":"**was going to** = j’avais l’intention ; **will** = décision sur le moment ; **be going to** = prédiction d’après un indice."},{"cle":{"type":"ordre","ids":["d","e","a","b","c","f"]},"explication":"**Before we go to bed, we will tell stories** : présent après *before*, *will* dans la principale."},{"cle":{"type":"trous","trous":[["stops"]]},"affichage":"stops","explication":"**stops** : le présent suit *as soon as*, même pour parler de l’avenir."}]$ex$::jsonb),
  ('1fdf1a99-b231-55cb-ad42-9ed95854c35f'::uuid, 1, 1, 5, 20, 3,
   $ex${"titre":"Bienvenue à Harbour School","competence":"comprendre-langue","situation":"Sam visite le site de son nouveau collège anglais. Il lit la page de présentation.","documents":[{"id":"page","type":"texte","genre":"article","titre":"Harbour School","blocs":["Harbour School was built in 1960. The classrooms are cleaned every evening. Lunch is served at noon in the big hall. The school bus is always full!"],"source":"Page écrite pour l’exercice"}],"questions":[{"enonce":"Touche les **trois participes passés** qui montrent que les phrases sont au passif.","aide":"Ils suivent *was* ou *are* / *is*.","type":"zone","document":"page","multiple":true},{"enonce":"Remets en ordre : « Le déjeuner est servi à midi. » La phrase commence par *Lunch*.","aide":"Sujet, *be*, participe passé, puis l’heure.","type":"ordre","items":[{"id":"a","texte":"served"},{"id":"b","texte":"at"},{"id":"c","texte":"Lunch"},{"id":"d","texte":"is"},{"id":"e","texte":"noon"}]},{"enonce":"Quelle est la phrase passive qui correspond à « They clean the classrooms every evening » ?","aide":"Le complément (*the classrooms*) devient sujet, puis *be* + participe passé.","type":"choix","options":[{"id":"a","texte":"The classrooms are cleaned every evening."},{"id":"b","texte":"The classrooms clean every evening."},{"id":"c","texte":"The classrooms are cleaning every evening."},{"id":"d","texte":"The classrooms cleaned every evening."}],"multiple":false}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"zone","ids":["m3","m9","m14"]},"explication":"**built**, **cleaned**, **served** : le passif se forme avec *be* + participe passé."},{"cle":{"type":"ordre","ids":["c","d","a","b","e"]},"explication":"**Lunch is served at noon.** : sujet + *is* + participe passé."},{"cle":{"type":"choix","ids":["a"]},"explication":"**The classrooms are cleaned every evening.** : présent simple actif → *are* + participe passé."}]$ex$::jsonb),
  ('1fdf1a99-b231-55cb-ad42-9ed95854c35f'::uuid, 2, 2, 10, 35, 4,
   $ex${"titre":"Les boutiques d’une petite ville","competence":"manier-langue","situation":"Le journal d’une petite ville écrit sur ses commerces. Il passe de l’actif au passif selon les époques.","documents":[{"id":"tab","type":"tableau","titre":"Active and passive","colonnes":["Temps","Phrase active","Phrase passive"],"lignes":[["Présent","They open the shop at nine.","The shop is opened at nine."],["Prétérit","They opened the shop in 2010.","?"],["Present perfect","They have opened a new shop.","?"],["Futur","They will open another shop.","?"]],"enteteLignes":true,"source":"Tableau écrit pour l’exercice"}],"questions":[{"enonce":"Touche la case où la phrase est **déjà** au passif, au présent.","aide":"Regarde la dernière colonne, première ligne.","type":"zone","document":"tab","multiple":false},{"enonce":"Complète la phrase passive du prétérit : « The shop ___ ___ in 2010. »","aide":"Le prétérit de *be* au singulier, puis le participe passé.","type":"trous","segments":["The shop ",0," ",1," in 2010."],"banque":["is","open","opened","was"]},{"enonce":"Quelle est la phrase passive du present perfect : « They have opened a new shop » ?","aide":"Present perfect de *be* : *has been* ; puis le participe passé.","type":"choix","options":[{"id":"a","texte":"A new shop was been opened."},{"id":"b","texte":"A new shop is been opened."},{"id":"c","texte":"A new shop has been opened."},{"id":"d","texte":"A new shop has opened be."}],"multiple":false},{"enonce":"Remets en ordre la phrase passive du futur. Elle commence par *Another*.","aide":"Au futur, on a *will be* + participe passé.","type":"ordre","items":[{"id":"a","texte":"be"},{"id":"b","texte":"opened"},{"id":"c","texte":"will"},{"id":"d","texte":"shop"},{"id":"e","texte":"Another"}]}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"zone","ids":["r0c2"]},"explication":"**The shop is opened at nine.** : *is* + participe passé, au présent."},{"cle":{"type":"trous","trous":[["was"],["opened"]]},"affichage":"was · opened","explication":"**The shop was opened in 2010.** : prétérit de *be* + participe passé."},{"cle":{"type":"choix","ids":["c"]},"explication":"**A new shop has been opened.** : *has been* + participe passé."},{"cle":{"type":"ordre","ids":["e","d","c","a","b"]},"explication":"**Another shop will be opened.** : *will* + *be* + participe passé."}]$ex$::jsonb),
  ('1fdf1a99-b231-55cb-ad42-9ed95854c35f'::uuid, 3, 3, 15, 50, 5,
   $ex${"titre":"Le vélo volé","competence":"analyser-document","situation":"Lina s’est fait voler son vélo à la gare. Elle prévient son père par message, puis lit un article du journal local.","documents":[{"id":"sms","type":"dialogue","modele":"sms","titre":"Messages de Lina et de son père","participants":[{"nom":"Lina","emoji":"👧","cote":"gauche"},{"nom":"Dad","emoji":"👨","cote":"droite"}],"repliques":[{"qui":"Lina","texte":"Dad, my bike was stolen this morning!"},{"qui":"Dad","texte":"Oh no! Where was it left?"},{"qui":"Lina","texte":"At the station. It was locked, but it’s gone."},{"qui":"Dad","texte":"The police will be told. Maybe it will be found."},{"qui":"Lina","texte":"I hope so. It was given to me by Grandpa!"}],"source":"Messages écrits pour l’exercice"},{"id":"journal","type":"texte","genre":"article","titre":"Newtown News","blocs":["The old bridge was built in 1890. It has been repaired twice. Next spring, a new library will be opened by the mayor, and the bridge will be closed for a week. Meetings are held in the town hall every Monday."],"source":"Article imaginé pour l’exercice"}],"questions":[{"enonce":"Touche le **participe passé** qui montre que Lina ne sait pas qui a pris son vélo.","aide":"C’est le verbe qui dit ce qui est arrivé au vélo ce matin.","type":"zone","document":"sms","multiple":false},{"enonce":"Dans l’article, associe chaque verbe passif à son temps.","aide":"Regarde la forme de *be* : *was*, *has been*, *will be*, *are*.","type":"association","gauche":[{"id":"g0","texte":"was built"},{"id":"g1","texte":"has been repaired"},{"id":"g2","texte":"will be opened"},{"id":"g3","texte":"are held"}],"droite":[{"id":"d0","texte":"présent"},{"id":"d1","texte":"futur"},{"id":"d2","texte":"prétérit"},{"id":"d3","texte":"present perfect"}]},{"enonce":"Touche le mot qui introduit **l’auteur** de l’action dans l’article.","aide":"L’auteur est le maire (*the mayor*).","type":"zone","document":"journal","multiple":false},{"enonce":"« They gave Lina a bike. » Quelle phrase passive est la plus courante ?","aide":"Avec *give*, la personne devient souvent le sujet du passif.","type":"choix","options":[{"id":"a","texte":"A bike was given Lina."},{"id":"b","texte":"Lina was given a bike."},{"id":"c","texte":"Lina was given to a bike."},{"id":"d","texte":"Lina has been given by a bike."}],"multiple":false},{"enonce":"Remets en ordre : « Mon téléphone a été retrouvé. » La phrase commence par *My*.","aide":"Present perfect passif : *has been* + participe passé.","type":"ordre","items":[{"id":"a","texte":"been"},{"id":"b","texte":"My"},{"id":"c","texte":"phone"},{"id":"d","texte":"found"},{"id":"e","texte":"has"}]}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"zone","ids":["m4"]},"explication":"**stolen** : on emploie le passif quand l’auteur de l’action est **inconnu**."},{"cle":{"type":"association","paires":{"g3":"d0","g2":"d1","g0":"d2","g1":"d3"}},"explication":"*was built* : prétérit ; *has been repaired* : present perfect ; *will be opened* : futur ; *are held* : présent."},{"cle":{"type":"zone","ids":["m20"]},"explication":"**by** introduit le complément d’agent. Il n’apparaît que quand l’auteur est important."},{"cle":{"type":"choix","ids":["b"]},"explication":"**Lina was given a bike.** : avec deux compléments, le plus courant fait de la personne le sujet."},{"cle":{"type":"ordre","ids":["b","c","e","a","d"]},"explication":"**My phone has been found.** : *has been* + participe passé."}]$ex$::jsonb),
  ('e770e18e-11eb-5667-b739-ccce649b9b76'::uuid, 1, 1, 5, 20, 3,
