   $ex$[{"cle":{"type":"zone","ids":["z1"]},"explication":"**Orange juice**, à £2.00, est le moins cher de la carte."},{"cle":{"type":"choix","ids":["a"]},"explication":"**I’d like an apple cake, please.** *Would like* est plus poli que *want*."},{"cle":{"type":"trous","trous":[["to"]]},"affichage":"to","explication":"**I’d like to order** : would like + to + verbe."}]$ex$::jsonb),
