   $ex${"titre":"Si seulement j’avais plus de temps","competence":"manier-langue","situation":"Ana envoie des messages à sa cousine un soir de grosse fatigue. Elle exprime plusieurs souhaits.","documents":[{"id":"ana","type":"dialogue","modele":"sms","titre":"Messages d’Ana et Rose","participants":[{"nom":"Ana","emoji":"👧","cote":"gauche"},{"nom":"Rose","emoji":"👩","cote":"droite"}],"repliques":[{"qui":"Ana","texte":"I wish I had more time! I have so much homework."},{"qui":"Ana","texte":"I wish it would stop raining, too."},{"qui":"Rose","texte":"Poor you! I wish I had studied harder for the maths test."}],"source":"Messages écrits pour l’exercice"}],"questions":[{"enonce":"Touche le mot qui exprime le souhait qu’une **situation change**.","aide":"C’est un modal placé avant *stop*.","type":"zone","document":"ana","multiple":false},{"enonce":"Associe chaque phrase à ce qu’elle exprime.","aide":"Regarde le temps qui suit *wish*.","type":"association","gauche":[{"id":"g0","texte":"I wish I had more time."},{"id":"g1","texte":"I wish I had studied harder."},{"id":"g2","texte":"I wish it would stop raining."}],"droite":[{"id":"d0","texte":"Regret sur le présent"},{"id":"d1","texte":"Souhait que ça change"},{"id":"d2","texte":"Regret sur le passé"}]},{"enonce":"Complète les deux regrets.","aide":"Le premier porte sur le présent, le second sur le passé.","type":"trous","segments":["I wish I ",0," taller. I wish I ",1," studied harder."],"banque":["would","have","had","were","am"]},{"enonce":"Remets en ordre : « Je voudrais qu’il arrête de pleuvoir ». La phrase commence par I.","aide":"Après *wish*, on met *it would*.","type":"ordre","items":[{"id":"a","texte":"it"},{"id":"b","texte":"raining"},{"id":"c","texte":"would"},{"id":"d","texte":"stop"},{"id":"e","texte":"wish"},{"id":"f","texte":"I"}]}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"zone","ids":["m14"]},"explication":"**would** : *wish* + *would* exprime le souhait que quelque chose change."},{"cle":{"type":"association","paires":{"g0":"d0","g2":"d1","g1":"d2"}},"explication":"Prétérit : présent. Past perfect : passé. *Would* : changement souhaité."},{"cle":{"type":"trous","trous":[["were"],["had"]]},"affichage":"were · had","explication":"**were** : forme irréelle de *be*. **had studied** : past perfect pour le passé."},{"cle":{"type":"ordre","ids":["f","e","a","c","d","b"]},"explication":"**I wish it would stop raining** : wish + sujet + would + base verbale."}]$ex$::jsonb),
  ('e770e18e-11eb-5667-b739-ccce649b9b76'::uuid, 3, 3, 15, 50, 5,
   $ex${"titre":"Une sortie qui a mal tourné","competence":"argumenter","situation":"Chloé a fait une randonnée sous la pluie. Elle écrit un e-mail à son père, qui lui répond par message.","documents":[{"id":"chloe","type":"texte","genre":"lettre","titre":"L’e-mail de Chloé","blocs":["Dear Dad, I’m wet and cold. I wish I had taken my umbrella. If only I had listened to you! I regret leaving my phone at home. I should have checked the weather."],"source":"E-mail écrit pour l’exercice"},{"id":"papa","type":"dialogue","modele":"sms","titre":"Le message du père","participants":[{"nom":"Chloé","emoji":"👧","cote":"gauche"},{"nom":"Papa","emoji":"👨","cote":"droite"}],"repliques":[{"qui":"Papa","texte":"I wish you would call me when you’re late! Would you like a lift home?"}],"source":"Message écrit pour l’exercice"}],"questions":[{"enonce":"Touche les **deux mots** qui renforcent le regret de Chloé.","aide":"Ils ouvrent une phrase exclamative.","type":"zone","document":"chloe","multiple":true},{"enonce":"Touche le verbe **en -ING** qui suit *regret*.","aide":"Il est tout près de *my phone*.","type":"zone","document":"chloe","multiple":false},{"enonce":"Quelle phrase veut dire « Je regrette d’avoir laissé mon téléphone » ?","aide":"*Regret* est suivi du verbe en -ING.","type":"choix","options":[{"id":"a","texte":"I regret leaving my phone at home."},{"id":"b","texte":"I regret to leaving my phone at home."},{"id":"c","texte":"I regret that leaving my phone at home."},{"id":"d","texte":"I regret leave my phone at home."}],"multiple":false},{"enonce":"Complète la demande du père.","aide":"Il souhaite que Chloé change son comportement.","type":"trous","segments":["I wish you ",0," call me when you’re late!"],"banque":["will","can","would","to"]},{"enonce":"Associe chaque phrase à sa nuance.","aide":"Pense au rôle de chaque phrase.","type":"association","gauche":[{"id":"g0","texte":"Would you like a lift?"},{"id":"g1","texte":"If only I had listened!"},{"id":"g2","texte":"I wish you a happy birthday."},{"id":"g3","texte":"I should have checked."}],"droite":[{"id":"d0","texte":"Offre polie"},{"id":"d1","texte":"Reproche à soi-même"},{"id":"d2","texte":"Regret fort sur le passé"},{"id":"d3","texte":"Vœu sans recul du temps"}]}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"zone","ids":["m13","m14"]},"explication":"**If only** : même construction que *wish*, avec plus d’émotion."},{"cle":{"type":"zone","ids":["m22"]},"explication":"**leaving** : *regret* + -ING (« regretter d’avoir fait »)."},{"cle":{"type":"choix","ids":["a"]},"explication":"**I regret leaving** : regret + -ING."},{"cle":{"type":"trous","trous":[["would"]]},"affichage":"would","explication":"**would** : *wish* + *would* demande que quelqu’un change d’habitude."},{"cle":{"type":"association","paires":{"g0":"d0","g3":"d1","g1":"d2","g2":"d3"}},"explication":"Chaque phrase a sa nuance : offre, regret fort, vœu ou reproche."}]$ex$::jsonb),
