   $ex${"titre":"Un courriel pour un stage d’anglais","competence":"argumenter","situation":"Chloé veut suivre un stage d’anglais d’été à Brighton. Elle écrit au centre de langues dans un style soigné.","documents":[{"id":"mail","type":"texte","genre":"lettre","titre":"Chloé’s email","blocs":["Dear Sir or Madam,","I am writing in order to ask about your summer English course in Brighton. I would like to study there so as to improve my speaking. My parents will pay in advance so that I can keep a place. I will write the dates down so as not to forget them.","Yours faithfully,","Chloé Martin"],"source":"Courriel écrit pour l’exercice"}],"questions":[{"enonce":"Touche le mot qui commence l’expression **formelle** du but dans la première phrase.","aide":"L’expression est *… order to*.","type":"zone","document":"mail","multiple":false},{"enonce":"Quelle expression peut remplacer *in order to* dans « I am writing in order to ask… » ?","aide":"Une autre expression formelle du but, avec la même idée.","type":"choix","options":[{"id":"a","texte":"for to"},{"id":"b","texte":"so as to"},{"id":"c","texte":"to for"},{"id":"d","texte":"so that to"}],"multiple":false},{"enonce":"Le but concerne la mère de Chloé : complète.","aide":"Quand le sujet change, on emploie une proposition.","type":"trous","segments":["Chloé is calling the school ",0," ",1," her mother can speak to the teacher."],"banque":["for","that","so","to"]},{"enonce":"Remets en ordre : « Il travaille dur pour réussir l’examen. » La phrase commence par *He*.","aide":"Le but : *to* + base verbale.","type":"ordre","items":[{"id":"a","texte":"hard"},{"id":"b","texte":"exam"},{"id":"c","texte":"He"},{"id":"d","texte":"pass"},{"id":"e","texte":"studies"},{"id":"f","texte":"to"},{"id":"g","texte":"the"}]},{"enonce":"Associe chaque construction à son emploi.","aide":"Regarde le sujet et la forme du but.","type":"association","gauche":[{"id":"g0","texte":"to + base verbale"},{"id":"g1","texte":"so as not to + base verbale"},{"id":"g2","texte":"so that + proposition"},{"id":"g3","texte":"for + nom"}],"droite":[{"id":"d0","texte":"aller chercher quelque chose"},{"id":"d1","texte":"le but courant, avec le même sujet"},{"id":"d2","texte":"le but négatif"},{"id":"d3","texte":"le but concernant un autre sujet"}]}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"zone","ids":["m7"]},"explication":"**in order to** + base verbale : c’est une forme plus formelle de *to*."},{"cle":{"type":"choix","ids":["b"]},"explication":"**so as to** a le même sens et le même registre que *in order to*."},{"cle":{"type":"trous","trous":[["so"],["that"]]},"affichage":"so · that","explication":"**so that** + proposition (avec un modal : *can*, *could*, *will*, *would*)."},{"cle":{"type":"ordre","ids":["c","e","a","f","d","g","b"]},"explication":"**He studies hard to pass the exam.** : *to* + base verbale exprime le but."},{"cle":{"type":"association","paires":{"g3":"d0","g0":"d1","g1":"d2","g2":"d3"}},"explication":"**to** : but courant ; **so as not to** : but négatif ; **so that** : autre sujet ; **for** + nom : aller chercher."}]$ex$::jsonb),
