   $ex$[{"cle":{"type":"zone","ids":["m2","m7","m15"]},"explication":"**went, saw, ate** : prétérits irréguliers de *go*, *see*, *eat*."},{"cle":{"type":"association","paires":{"g2":"d0","g1":"d1","g3":"d2","g0":"d3"}},"explication":"*Go → went*, *see → saw*, *take → took* sont irréguliers ; *study → studied* est régulier."},{"cle":{"type":"trous","trous":[["went"]]},"affichage":"went","explication":"**went** : prétérit irrégulier de *go*."}]$ex$::jsonb),
  ('d4b7aa12-d4ff-5b4f-822a-ee238be24c17'::uuid, 2, 2, 10, 35, 4,
   $ex${"titre":"Le week-end d’Emma et Jack","competence":"manier-langue","situation":"Emma et Jack se racontent leur week-end par messages. Jack n’a pas tout fait comme prévu.","documents":[{"id":"week","type":"dialogue","modele":"sms","titre":"Messages d’Emma et Jack","participants":[{"nom":"Emma","emoji":"👧","cote":"gauche"},{"nom":"Jack","emoji":"👦","cote":"droite"}],"repliques":[{"qui":"Emma","texte":"Did you go to the match?"},{"qui":"Jack","texte":"No, I didn’t. I stayed home."},{"qui":"Emma","texte":"Did you see the new film?"},{"qui":"Jack","texte":"Yes! I loved it."}],"source":"Messages écrits pour l’exercice"}],"questions":[{"enonce":"Touche le mot qui sert à **nier** au prétérit.","aide":"Il est dans la réponse de Jack.","type":"zone","document":"week","multiple":false},{"enonce":"Range chaque phrase selon qu’elle est correcte ou fautive.","aide":"Après *did* ou *didn’t*, le verbe est à la base verbale. *Stop* double le p.","type":"categories","categories":[{"id":"c0","texte":"Correcte"},{"id":"c1","texte":"Fautive"}],"items":[{"id":"i0","texte":"Did you saw the film?"},{"id":"i1","texte":"Did you see the film?"},{"id":"i2","texte":"We stoped at six."},{"id":"i3","texte":"I didn’t went to school."},{"id":"i4","texte":"We stopped at six."},{"id":"i5","texte":"I didn’t go to school."}]},{"enonce":"Complète au prétérit.","aide":"Consonne + y devient -ied.","type":"trous","segments":["She ",0," (study) all night."],"banque":["studid","studyed","studied","studies"]},{"enonce":"Remets en ordre : « As-tu vu le nouveau film ? ». La phrase commence par Did.","aide":"Après *Did you*, le verbe est à la base verbale.","type":"ordre","items":[{"id":"a","texte":"the"},{"id":"b","texte":"you"},{"id":"c","texte":"film"},{"id":"d","texte":"Did"},{"id":"e","texte":"see"},{"id":"f","texte":"new"}]}]}$ex$::jsonb,
