  ('d4b7aa12-d4ff-5b4f-822a-ee238be24c17'::uuid, 3, 3, 15, 50, 5,
   $ex${"titre":"La visite du Grand Incendie","competence":"se-reperer-temps","situation":"Une classe est allée à Londres. Elle a étudié le Grand Incendie de 1666. Voici une frise et le compte rendu de la visite.","documents":[{"id":"frise","type":"frise","titre":"Great Fire of London","debut":1660,"fin":1710,"pas":10,"periodes":[],"evenements":[{"id":"z1","date":1666,"nom":"Great Fire"},{"id":"z2","date":1675,"nom":"Work starts"},{"id":"z3","date":1708,"nom":"Last stone"}],"source":"Frise écrite pour l’exercice"},{"id":"visite","type":"texte","genre":"article","titre":"Our trip to London","blocs":["Last week our class visited London. We saw St Paul’s Cathedral. Our guide told us that the fire started in 1666. She said that many houses used to be made of wood. We didn’t climb the dome because it was closed."],"source":"Compte rendu écrit pour l’exercice"}],"questions":[{"enonce":"Touche l’événement qui s’est produit en **1666**.","aide":"Repère la date sur la frise.","type":"zone","document":"frise","multiple":false},{"enonce":"Touche les **deux verbes irréguliers** du compte rendu.","aide":"Ils ne se terminent pas par -ed.","type":"zone","document":"visite","multiple":true},{"enonce":"Complète les deux phrases.","aide":"Le premier verbe est daté. Le second est une habitude passée.","type":"trous","segments":["The fire ",0," in 1666. Before the fire, many houses ",1," to be made of wood."],"banque":["start","use","used","started"]},{"enonce":"Pourquoi n’écrit-on pas « The fire has started in 1666 » ?","aide":"Regarde le repère de temps.","type":"choix","options":[{"id":"a","texte":"Parce que *fire* est irrégulier"},{"id":"b","texte":"Parce que *started* est au futur"},{"id":"c","texte":"Parce qu’il manque un adverbe"},{"id":"d","texte":"Une date précise impose le prétérit"}],"multiple":false},{"enonce":"Remets en ordre : « Nous ne sommes pas montés sur le dôme ». La phrase commence par We.","aide":"Après *didn’t*, le verbe est à la base verbale.","type":"ordre","items":[{"id":"a","texte":"didn’t"},{"id":"b","texte":"the"},{"id":"c","texte":"We"},{"id":"d","texte":"climb"},{"id":"e","texte":"dome"}]}]}$ex$::jsonb,
