  ('53a4f727-aa5d-5cc0-89cf-8563f4b2d90a'::uuid, 1, 1, 5, 20, 3,
   $ex${"titre":"Que faisais-tu à huit heures ?","competence":"comprendre-langue","situation":"Emma a appelé Tom hier soir sans réponse. Le lendemain, ils se racontent leur soirée par messages.","documents":[{"id":"sms","type":"dialogue","modele":"sms","titre":"Messages d’Emma et Tom","participants":[{"nom":"Emma","emoji":"👧","cote":"gauche"},{"nom":"Tom","emoji":"👦","cote":"droite"}],"repliques":[{"qui":"Emma","texte":"Where were you at eight o’clock last night? I called you."},{"qui":"Tom","texte":"Sorry! I was watching a film with my sister."},{"qui":"Emma","texte":"No problem. I was doing my homework."},{"qui":"Tom","texte":"We were eating pizza, too!"}],"source":"Messages écrits pour l’exercice"}],"questions":[{"enonce":"Touche les **trois verbes** en **-ING** qui disent ce que chacun était en train de faire.","aide":"Cherche les verbes qui se terminent par -ing.","type":"zone","document":"sms","multiple":true},{"enonce":"Complète avec l’auxiliaire qui convient.","aide":"Le sujet est pluriel (Tom et sa sœur) et la scène se passe hier soir.","type":"trous","segments":["Last night at eight, Tom and his sister ",0," eating pizza."],"banque":["are","was","were","do"]},{"enonce":"Que faisait Emma à huit heures ?","aide":"Relis la réponse d’Emma à Tom.","type":"choix","options":[{"id":"a","texte":"Elle faisait ses devoirs."},{"id":"b","texte":"Elle mangeait une pizza."},{"id":"c","texte":"Elle téléphonait à sa mère."},{"id":"d","texte":"Elle regardait un film."}],"multiple":false}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"zone","ids":["m14","m24","m29"]},"explication":"**watching**, **doing** et **eating** : was / were + verbe en **-ING** dit une action en cours à un moment du passé."},{"cle":{"type":"trous","trous":[["were"]]},"affichage":"were","explication":"**were** : sujet pluriel au passé, donc **were** + verbe en -ING."},{"cle":{"type":"choix","ids":["a"]},"explication":"Emma dit « I was doing my homework » : à huit heures, elle **faisait ses devoirs**."}]$ex$::jsonb),
  ('53a4f727-aa5d-5cc0-89cf-8563f4b2d90a'::uuid, 2, 2, 10, 35, 4,
   $ex${"titre":"Un témoin chez la police","competence":"analyser-document","situation":"Un témoin raconte à la police ce qu’il a vu devant un magasin. Il décrit d’abord ce qu’il faisait, puis ce qui s’est passé.","documents":[{"id":"temoin","type":"texte","genre":"article","titre":"Witness statement","blocs":["I was walking my dog in Park Road at nine when I heard a loud noise.","While I was crossing the street, a man ran out of the shop. He was carrying a big bag."],"source":"Témoignage écrit pour l’exercice"}],"questions":[{"enonce":"Touche les **deux verbes** qui disent ce qui **survient** et interrompt le témoin (verbes au prétérit simple).","aide":"Ces actions sont courtes et soudaines.","type":"zone","document":"temoin","multiple":true},{"enonce":"Range chaque verbe du témoignage : **décor** de la scène ou **événement** qui survient ?","aide":"Le décor dure ; l’événement interrompt.","type":"categories","categories":[{"id":"c0","texte":"Le décor (BE + -ING)"},{"id":"c1","texte":"L’événement (prétérit simple)"}],"items":[{"id":"i0","texte":"was crossing"},{"id":"i1","texte":"heard"},{"id":"i2","texte":"ran out"},{"id":"i3","texte":"was carrying"},{"id":"i4","texte":"was walking"}]},{"enonce":"Complète avec le verbe qui convient.","aide":"L’événement qui interrompt est une action courte.","type":"trous","segments":["I was walking my dog when I ",0," a noise."],"banque":["heard","hear","hearing","was hearing"]},{"enonce":"Remets en ordre : « Pendant que je traversais la rue, un homme est sorti en courant. » La phrase commence par While.","aide":"Le décor en -ING vient avant l’événement.","type":"ordre","items":[{"id":"a","texte":"was crossing"},{"id":"b","texte":"a man"},{"id":"c","texte":"the street,"},{"id":"d","texte":"ran out"},{"id":"e","texte":"While I"}]}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"zone","ids":["m12","m24"]},"explication":"**heard** et **ran** : l’événement qui survient est au prétérit simple."},{"cle":{"type":"categories","items":{"i0":"c0","i1":"c1","i2":"c1","i3":"c0","i4":"c0"}},"explication":"Le **décor** (action longue) est en **BE + -ING** ; l’**événement** (action courte) est au prétérit simple."},{"cle":{"type":"trous","trous":[["heard"]]},"affichage":"heard","explication":"**heard** : l’action courte qui survient se met au prétérit simple."},{"cle":{"type":"ordre","ids":["e","a","c","b","d"]},"explication":"**While I was crossing the street, a man ran out** : *while* + décor en BE + -ING, puis l’événement."}]$ex$::jsonb),
  ('53a4f727-aa5d-5cc0-89cf-8563f4b2d90a'::uuid, 3, 3, 15, 50, 5,
   $ex${"titre":"La panne de courant","competence":"argumenter","situation":"Ben raconte à sa cousine Zoe la soirée où le courant s’est coupé. Elle lui répond avec une anecdote semblable.","documents":[{"id":"mail","type":"texte","genre":"lettre","titre":"Ben’s message","blocs":["Hi Zoe, guess what happened last night! At half past seven we were having dinner when the lights went out.","Dad was cooking pasta, Mum was setting the table and I was chatting with Luke online. While we were looking for candles, our dog was barking like crazy. Then the lights came back. Love, Ben"],"source":"Message écrit pour l’exercice"},{"id":"zoe","type":"dialogue","modele":"sms","titre":"Réponse de Zoe","participants":[{"nom":"Zoe","emoji":"👩","cote":"gauche"},{"nom":"Ben","emoji":"👦","cote":"droite"}],"repliques":[{"qui":"Zoe","texte":"That’s funny! Last week my brother was playing a video game when the power went off."},{"qui":"Zoe","texte":"He was shouting at the TV while I was laughing."}],"source":"Messages écrits pour l’exercice"}],"questions":[{"enonce":"Touche le verbe qui dit **ce qui a interrompu** le dîner de la famille.","aide":"Cherche l’action courte, au prétérit simple.","type":"zone","document":"mail","multiple":false},{"enonce":"Associe chaque personne à ce qu’elle faisait quand les lumières se sont éteintes.","aide":"Relis le message de Ben, phrase par phrase.","type":"association","gauche":[{"id":"g0","texte":"Dad"},{"id":"g1","texte":"Mum"},{"id":"g2","texte":"Ben"},{"id":"g3","texte":"The dog"}],"droite":[{"id":"d0","texte":"was setting the table"},{"id":"d1","texte":"was chatting online"},{"id":"d2","texte":"was cooking pasta"},{"id":"d3","texte":"was barking"}]},{"enonce":"Dans le message de Zoe, touche les **deux verbes** de la phrase avec *while* : deux actions **simultanées**.","aide":"Les deux actions se passent en même temps.","type":"zone","document":"zoe","multiple":true},{"enonce":"Quelles phrases sont **correctes** ? (deux bonnes réponses)","aide":"Un verbe d’état n’accepte pas -ING, et il faut was / were devant le verbe en -ING.","type":"choix","options":[{"id":"a","texte":"The dog was barking while we were looking for candles."},{"id":"b","texte":"I was knowing where the candles were."},{"id":"c","texte":"We were eating when the lights went out."},{"id":"d","texte":"While the lights were going out, we eating pasta."}],"multiple":true},{"enonce":"Complète avec le bon verbe.","aide":"C’est l’événement qui interrompt la partie.","type":"trous","segments":["Zoe’s brother was playing a game when the power ",0," off."],"banque":["went","goes","gone","was going"]}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"zone","ids":["m18"]},"explication":"**went** : « the lights went out » est l’événement qui interrompt le dîner (action en cours)."},{"cle":{"type":"association","paires":{"g1":"d0","g2":"d1","g0":"d2","g3":"d3"}},"explication":"Chacun était **en train de** faire une action : le décor est en **was / were + -ING**."},{"cle":{"type":"zone","ids":["m18","m25"]},"explication":"**shouting** et **laughing** : *while* relie deux actions simultanées, toutes deux en BE + -ING."},{"cle":{"type":"choix","ids":["a","c"]},"explication":"Les phrases 1 et 3 sont correctes. « I was knowing » est faux (**know** est un verbe d’état) et la dernière oublie **were**."},{"cle":{"type":"trous","trous":[["went"]]},"affichage":"went","explication":"**went** : l’événement qui survient est au prétérit simple (*the power went off*)."}]$ex$::jsonb),
  ('344faec7-d4ca-5c5a-9d7d-fbacb9dcc0bc'::uuid, 1, 1, 5, 20, 3,
   $ex${"titre":"À qui est ce sac ?","competence":"comprendre-langue","situation":"Après le cours, des affaires traînent dans la salle. Une professeure demande à qui elles appartiennent.","documents":[{"id":"salle","type":"dialogue","modele":"sms","titre":"Dans la salle de classe","participants":[{"nom":"Teacher","emoji":"👩‍🏫","cote":"gauche"},{"nom":"Paul","emoji":"👦","cote":"droite"},{"nom":"Kate","emoji":"👧","cote":"droite"}],"repliques":[{"qui":"Teacher","texte":"Whose bag is this?"},{"qui":"Paul","texte":"It’s mine."},{"qui":"Teacher","texte":"And this pen?"},{"qui":"Kate","texte":"It’s Tom’s, not mine."}],"source":"Dialogue écrit pour l’exercice"}],"questions":[{"enonce":"Touche les **deux pronoms possessifs** employés dans le dialogue.","aide":"Ce mot remplace « mon sac » ou « mon stylo » : il est employé seul.","type":"zone","document":"salle","multiple":true},{"enonce":"Touche le mot qui **pose la question** du propriétaire.","aide":"C’est le mot interrogatif au début du dialogue.","type":"zone","document":"salle","multiple":false},{"enonce":"Comment dit-on « le stylo de Tom » ?","aide":"Avec une personne, l’anglais met le possesseur avant l’objet.","type":"choix","options":[{"id":"a","texte":"The pen of Tom"},{"id":"b","texte":"Tom’s pen"},{"id":"c","texte":"Tom pen"},{"id":"d","texte":"Tom’s of pen"}],"multiple":false}]}$ex$::jsonb,
