   $ex${"titre":"Une lettre sur ma maison","competence":"manier-langue","situation":"Zoe reçoit une lettre de sa correspondante anglaise. Elle y décrit sa maison et sa famille.","documents":[{"id":"lettre","type":"texte","genre":"lettre","titre":"Une lettre de Hannah","blocs":["Hi Zoe! Let me tell you about my house.","My brother’s room is small, but my parents’ room is big. The children’s toys are in the garden, and my sister’s bike is there too.","Today’s weather is great, so come on Saturday!"],"source":"Lettre écrite pour l’exercice"}],"questions":[{"enonce":"Touche le mot qui exprime la possession avec une **expression de temps**.","aide":"Ce mot parle du jour d’aujourd’hui.","type":"zone","document":"lettre","multiple":false},{"enonce":"Range chaque groupe selon la marque du génitif.","aide":"Singulier : ’s. Pluriel en -s : l’apostrophe seule. Pluriel sans -s : ’s.","type":"categories","categories":[{"id":"c0","texte":"’s (singulier)"},{"id":"c1","texte":"’ seule (pluriel en -s)"},{"id":"c2","texte":"’s (pluriel irrégulier)"}],"items":[{"id":"i0","texte":"the children’s toys"},{"id":"i1","texte":"my sister’s bike"},{"id":"i2","texte":"the girls’ room"},{"id":"i3","texte":"the men’s team"},{"id":"i4","texte":"my parents’ room"},{"id":"i5","texte":"my brother’s room"}]},{"enonce":"Complète avec la structure qui convient pour un objet.","aide":"On n’emploie pas ’s avec une maison.","type":"trous","segments":["The roof ",0," the house is new."],"banque":["of","to","’s","from"]},{"enonce":"Associe chaque groupe anglais à sa traduction.","aide":"En anglais, le possesseur ou la notion de temps passe avant.","type":"association","gauche":[{"id":"g0","texte":"my father’s car"},{"id":"g1","texte":"the end of the film"},{"id":"g2","texte":"today’s newspaper"},{"id":"g3","texte":"the girls’ room"}],"droite":[{"id":"d0","texte":"le journal d’aujourd’hui"},{"id":"d1","texte":"la fin du film"},{"id":"d2","texte":"la voiture de mon père"},{"id":"d3","texte":"la chambre des filles"}]}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"zone","ids":["m34"]},"explication":"**Today’s** weather : le génitif ’s s’emploie aussi avec des expressions de temps."},{"cle":{"type":"categories","items":{"i0":"c2","i1":"c0","i2":"c1","i3":"c2","i4":"c1","i5":"c0"}},"explication":"**brother’s, sister’s** (singulier) ; **parents’, girls’** (pluriel en -s) ; **children’s, men’s** (pluriel irrégulier : ’s)."},{"cle":{"type":"trous","trous":[["of"]]},"affichage":"of","explication":"**The roof of the house** : pour un objet, on emploie la structure avec **of**."},{"cle":{"type":"association","paires":{"g2":"d0","g1":"d1","g0":"d2","g3":"d3"}},"explication":"**’s** pour les personnes et le temps, **of** pour les objets, apostrophe seule pour un pluriel en -s."}]$ex$::jsonb),
