   $ex${"titre":"Les affaires oubliées après la fête","competence":"analyser-document","situation":"Après une fête, Tom et Anna rangent la salle. Ils consultent la liste des objets trouvés pour les rendre à leurs propriétaires.","documents":[{"id":"fete","type":"dialogue","modele":"sms","titre":"Tom et Anna rangent","participants":[{"nom":"Tom","emoji":"👦","cote":"gauche"},{"nom":"Anna","emoji":"👧","cote":"droite"}],"repliques":[{"qui":"Tom","texte":"Whose bag is this?"},{"qui":"Anna","texte":"Look at the list! It’s Kate’s."},{"qui":"Tom","texte":"And the umbrella?"},{"qui":"Anna","texte":"That’s the Smiths’."}],"source":"Dialogue écrit pour l’exercice"},{"id":"liste","type":"tableau","titre":"Objets trouvés après la fête","colonnes":["Objet","Propriétaire"],"lignes":[["the bag","Kate"],["the phone","Paul"],["the umbrella","the Smiths"],["the scarf","Anna"]],"source":"Liste écrite pour l’exercice"}],"questions":[{"enonce":"Touche les **deux génitifs** employés par Anna.","aide":"Cherche les noms suivis d’une apostrophe.","type":"zone","document":"fete","multiple":true},{"enonce":"D’après la liste, associe chaque propriétaire à l’adjectif possessif qui convient.","aide":"Le possessif s’accorde avec le possesseur, pas avec l’objet.","type":"association","gauche":[{"id":"g0","texte":"Paul / the phone"},{"id":"g1","texte":"Anna / the scarf"},{"id":"g2","texte":"the Smiths / the umbrella"},{"id":"g3","texte":"the house / the roof"}],"droite":[{"id":"d0","texte":"their umbrella"},{"id":"d1","texte":"her scarf"},{"id":"d2","texte":"his phone"},{"id":"d3","texte":"its roof"}]},{"enonce":"Complète avec les pronoms possessifs : le sac est à Kate, le parapluie aux Smiths.","aide":"Le pronom possessif remplace « le sac de Kate » en un seul mot.","type":"trous","segments":["The bag is Kate’s: it’s ",0,". The umbrella is the Smiths’: it’s ",1,"."],"banque":["theirs","hers","yours","ours","his"]},{"enonce":"Quelle phrase est correcte pour parler de la maison ?","aide":"Its (possessif) n’a pas d’apostrophe.","type":"choix","options":[{"id":"a","texte":"The house is old, but its roof is new."},{"id":"b","texte":"The house is old, but hers roof is new."},{"id":"c","texte":"The house is old, but it’s roof is new."},{"id":"d","texte":"The house is old, but their roof is new."}],"multiple":false},{"enonce":"Tom retrouve le foulard d’Anna. Complète la question qu’il pose.","aide":"On demande à qui appartient le foulard.","type":"trous","segments":[0," scarf is this? — It’s Anna’s."],"banque":["Who’s","Whose","Which","Who"]}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"zone","ids":["m9","m15"]},"explication":"**Kate’s** (singulier : ’s) et **Smiths’** (pluriel en -s : l’apostrophe seule)."},{"cle":{"type":"association","paires":{"g2":"d0","g1":"d1","g0":"d2","g3":"d3"}},"explication":"**his** (Paul), **her** (Anna), **their** (les Smiths), **its** (la maison) : le possessif s’accorde avec le **possesseur**."},{"cle":{"type":"trous","trous":[["hers"],["theirs"]]},"affichage":"hers · theirs","explication":"**hers** (Kate) et **theirs** (les Smiths) : le pronom possessif remplace tout le groupe et n’est jamais suivi d’un nom."},{"cle":{"type":"choix","ids":["a"]},"explication":"**its roof** : its est le possessif. *It’s* est la contraction de « it is »."},{"cle":{"type":"trous","trous":[["whose"]]},"affichage":"Whose","explication":"**Whose scarf is this?** *Whose* demande le possesseur ; *who’s* veut dire « who is »."}]$ex$::jsonb),
  ('e4367fdc-2634-5f7a-b171-0516468ab282'::uuid, 1, 1, 5, 20, 4,
   $ex${"titre":"Une carte postale d’Édimbourg","competence":"comprendre-langue","situation":"Lena passe le week-end à Édimbourg. Elle écrit une carte postale à sa grand-mère.","documents":[{"id":"carte","type":"fiche","modele":"carte-postale","titre":"Postcard","entete":"Greetings from Edinburgh","emoji":"🏰","lignes":[{"texte":"What a beautiful city!","id":"z1"},{"texte":"How cold it is!","id":"z2"},{"texte":"What lovely people!","id":"z3"},{"texte":"What a pity you aren’t here!","id":"z4"}],"pied":"Love, Lena","teinte":"bleu","source":"Carte écrite pour l’exercice"}],"questions":[{"enonce":"Touche les **deux phrases** qui commencent par *What a* (un nom au singulier).","aide":"Cherche les phrases où *What* est suivi de l’article *a*.","type":"zone","document":"carte","multiple":true},{"enonce":"Pourquoi n’y a-t-il pas de *a* dans « What lovely people! » ?","aide":"On met *a* seulement devant un nom singulier.","type":"choix","options":[{"id":"a","texte":"Parce qu’on ne met jamais *a* après *what*"},{"id":"b","texte":"Parce que *lovely* commence par une consonne"},{"id":"c","texte":"Parce que la phrase est au passé"},{"id":"d","texte":"Parce que *people* est un pluriel"}],"multiple":false},{"enonce":"Complète l’exclamation.","aide":"Le mot est suivi d’un nom (*cakes*).","type":"trous","segments":[0," delicious cakes!"],"banque":["What","So","How","Such"]},{"enonce":"Remets en ordre : « Quelle belle journée ! » La phrase commence par *What*.","aide":"Après *What*, l’article vient avant l’adjectif.","type":"ordre","items":[{"id":"a","texte":"a"},{"id":"b","texte":"day"},{"id":"c","texte":"beautiful"},{"id":"d","texte":"What"}]}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"zone","ids":["z1","z4"]},"explication":"**What a beautiful city!** et **What a pity…!** : devant un nom singulier dénombrable, on dit *What a* + nom."},{"cle":{"type":"choix","ids":["d"]},"explication":"**people** est un pluriel : après *What*, un nom pluriel s’emploie **sans article**."},{"cle":{"type":"trous","trous":[["what"]]},"affichage":"What","explication":"**What delicious cakes!** : *what* introduit une exclamation devant un nom."},{"cle":{"type":"ordre","ids":["d","a","c","b"]},"explication":"**What a beautiful day!** : What + a + adjectif + nom."}]$ex$::jsonb),
  ('e4367fdc-2634-5f7a-b171-0516468ab282'::uuid, 2, 2, 10, 35, 4,
   $ex${"titre":"Le voyage scolaire à Bath","competence":"manier-langue","situation":"Zoe revient d’une sortie scolaire à Bath. Elle raconte tout à son ami Ben par messages.","documents":[{"id":"sms","type":"dialogue","modele":"sms","titre":"Messages de Zoe et Ben","participants":[{"nom":"Zoe","emoji":"👧","cote":"gauche"},{"nom":"Ben","emoji":"👦","cote":"droite"}],"repliques":[{"qui":"Zoe","texte":"The trip to Bath was great! What a lovely town!"},{"qui":"Ben","texte":"How lucky you are! Which part did you like best?"},{"qui":"Zoe","texte":"The Roman baths! They are such old buildings!"},{"qui":"Ben","texte":"No way! I’m so jealous!"}],"source":"Messages écrits pour l’exercice"}],"questions":[{"enonce":"Touche les **deux mots** qui introduisent une exclamation dans les messages.","aide":"L’un est suivi d’un nom, l’autre d’un adjectif.","type":"zone","document":"sms","multiple":true},{"enonce":"Range chaque exclamation selon le mot qui la commence.","aide":"*What* est suivi d’un nom, *how* d’un adjectif ou d’un adverbe.","type":"categories","categories":[{"id":"c0","texte":"What"},{"id":"c1","texte":"How"}],"items":[{"id":"i0","texte":"___ a great idea!"},{"id":"i1","texte":"___ tall your brother is!"},{"id":"i2","texte":"___ funny he is!"},{"id":"i3","texte":"___ an amazing view!"},{"id":"i4","texte":"___ delicious cakes!"},{"id":"i5","texte":"___ quickly she runs!"}]},{"enonce":"Complète la phrase.","aide":"Un adjectif seul suit ce mot.","type":"trous","segments":["She is ",0," kind!"],"banque":["such a","so","what","such"]},{"enonce":"Comment dit-on « Comme elle court vite ! » ?","aide":"Après *how*, l’adjectif ou l’adverbe vient tout de suite, puis le sujet et le verbe.","type":"choix","options":[{"id":"a","texte":"What fast she runs!"},{"id":"b","texte":"How fast she runs!"},{"id":"c","texte":"How fast does she run!"},{"id":"d","texte":"How she runs fast!"}],"multiple":false}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"zone","ids":["m6","m10"]},"explication":"**What** (devant le nom *town*) et **How** (devant l’adjectif *lucky*) : ce sont les deux mots de l’exclamation."},{"cle":{"type":"categories","items":{"i0":"c0","i1":"c1","i2":"c1","i3":"c0","i4":"c0","i5":"c1"}},"explication":"**What** + nom (*idea*, *cakes*, *view*) ; **how** + adjectif ou adverbe (*funny*, *quickly*, *tall*)."},{"cle":{"type":"trous","trous":[["so"]]},"affichage":"so","explication":"**so kind** : *so* est suivi d’un adjectif seul ; *such* demande un nom."},{"cle":{"type":"choix","ids":["b"]},"explication":"**How fast she runs!** : how + adverbe + sujet + verbe, **sans inversion**."}]$ex$::jsonb),
  ('e4367fdc-2634-5f7a-b171-0516468ab282'::uuid, 3, 3, 15, 50, 5,
   $ex${"titre":"Le camp d’été du lac","competence":"manier-langue","situation":"Mia passe une semaine dans un camp d’été au bord du lac Windermere. Elle lit l’affiche du camp, puis écrit à sa grand-mère.","documents":[{"id":"affiche","type":"fiche","modele":"affiche","titre":"Camp poster","entete":"Lakeside Summer Camp","sousTitre":"Windermere — July","emoji":"⛺","lignes":[{"texte":"What a place for a holiday!","id":"z1"},{"texte":"What great activities!","id":"z2"},{"texte":"Climbing, canoeing and campfires","id":"z3"},{"texte":"How exciting your week will be!","id":"z4"}],"teinte":"vert","source":"Affiche écrite pour l’exercice"},{"id":"mail","type":"texte","genre":"lettre","titre":"Mia’s email","blocs":["Dear Gran,","The camp is so big and the food is so good! We sleep in such a lovely cabin, with six bunk beds. Yesterday it rained: what a pity, no canoeing! But Mr Lee makes such delicious pancakes. How happy I am here!","Love, Mia"],"source":"Courriel écrit pour l’exercice"}],"questions":[{"enonce":"Touche la ligne où *What* est suivi d’un **nom pluriel**, sans article.","aide":"Cherche la ligne qui n’a pas *a* après *What*.","type":"zone","document":"affiche","multiple":false},{"enonce":"Touche les **deux mots *so*** : ils sont suivis d’un adjectif seul.","aide":"Il y en a un devant *big* et un devant *good*.","type":"zone","document":"mail","multiple":true},{"enonce":"Associe chaque construction à ce qui la suit.","aide":"Regarde si le nom est singulier ou pluriel, et s’il y a un nom ou non.","type":"association","gauche":[{"id":"g0","texte":"so"},{"id":"g1","texte":"such a"},{"id":"g2","texte":"such"},{"id":"g3","texte":"What a"}],"droite":[{"id":"d0","texte":"un adjectif + un nom pluriel (such delicious pancakes)"},{"id":"d1","texte":"un adjectif + un nom singulier (such a lovely cabin)"},{"id":"d2","texte":"un adjectif ou un adverbe seul (so big)"},{"id":"d3","texte":"un nom singulier dans une exclamation (What a pity!)"}]},{"enonce":"Mia hésite devant « How beautiful is this lake! ». Que faut-il corriger ?","aide":"L’anglais ne fait pas d’inversion dans l’exclamation.","type":"choix","options":[{"id":"a","texte":"Ne rien corriger : la phrase est déjà correcte comme ça"},{"id":"b","texte":"Ajouter *a* après *How* : *How a beautiful is this lake!*"},{"id":"c","texte":"Remettre le sujet avant le verbe : *How beautiful this lake is!*"},{"id":"d","texte":"Remplacer *How* par *What* : *What beautiful is this lake!*"}],"multiple":false},{"enonce":"Complète la phrase.","aide":"Le nom *day* est au singulier, avec *a*.","type":"trous","segments":["It was ",0," a lovely day!"],"banque":["such","how","so","what"]}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"zone","ids":["z2"]},"explication":"**What great activities!** : *activities* est un pluriel, donc pas d’article."},{"cle":{"type":"zone","ids":["m5","m11"]},"explication":"**so big** et **so good** : *so* + adjectif. Pour un nom, on emploie *such* (*such a lovely cabin*)."},{"cle":{"type":"association","paires":{"g2":"d0","g1":"d1","g0":"d2","g3":"d3"}},"explication":"**so** + adjectif ; **such a** + adjectif + nom singulier ; **such** + adjectif + nom pluriel ; **What a** + nom singulier."},{"cle":{"type":"choix","ids":["c"]},"explication":"**How beautiful this lake is!** : dans une exclamation, le sujet reste **avant** le verbe."},{"cle":{"type":"trous","trous":[["such"]]},"affichage":"such","explication":"**such a lovely day** : *such a* + adjectif + nom singulier."}]$ex$::jsonb),
  ('66a3ad58-1283-5ddb-a798-8120805cf7ad'::uuid, 1, 1, 5, 20, 3,
   $ex${"titre":"Où est Leo ?","competence":"comprendre-langue","situation":"Leo n’est pas en classe ce matin. Max et Anna se demandent pourquoi, en envoyant des messages.","documents":[{"id":"msg","type":"dialogue","modele":"sms","titre":"Messages de Max et Anna","participants":[{"nom":"Max","emoji":"👦","cote":"gauche"},{"nom":"Anna","emoji":"👧","cote":"droite"}],"repliques":[{"qui":"Max","texte":"Leo isn’t in class. He might be ill."},{"qui":"Anna","texte":"He must be ill! He was coughing yesterday."},{"qui":"Max","texte":"Or he may be late. The bus is slow."}],"source":"Messages écrits pour l’exercice"}],"questions":[{"enonce":"Touche le modal par lequel Anna se dit **presque sûre** de la cause.","aide":"Elle ne dit pas « peut-être » mais « sûrement ».","type":"zone","document":"msg","multiple":false},{"enonce":"Associe chaque modal à son degré de certitude.","aide":"Du plus sûr au moins sûr, puis le contraire.","type":"association","gauche":[{"id":"g0","texte":"must"},{"id":"g1","texte":"might"},{"id":"g2","texte":"can’t"}],"droite":[{"id":"d0","texte":"Simplement possible"},{"id":"d1","texte":"Presque certain"},{"id":"d2","texte":"Impossible"}]},{"enonce":"Que veut dire « He can’t be at home » ?","aide":"Ici, *can’t* dit que c’est impossible.","type":"choix","options":[{"id":"a","texte":"Il ne peut pas être chez lui"},{"id":"b","texte":"Il ne doit pas rentrer chez lui"},{"id":"c","texte":"Il ne sait pas être chez lui"},{"id":"d","texte":"Il n’a pas le droit d’être chez lui"}],"multiple":false}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"zone","ids":["m9"]},"explication":"**must** : la quasi-certitude."},{"cle":{"type":"association","paires":{"g1":"d0","g0":"d1","g2":"d2"}},"explication":"*Must* : presque sûr. *Might* : possible. *Can’t* : impossible."},{"cle":{"type":"choix","ids":["a"]},"explication":"**Il ne peut pas être chez lui** : *can’t* exprime la certitude négative."}]$ex$::jsonb),
  ('66a3ad58-1283-5ddb-a798-8120805cf7ad'::uuid, 2, 2, 10, 35, 4,
   $ex${"titre":"Qui a mangé le gâteau ?","competence":"raisonner","situation":"Le gâteau a disparu de la cuisine à 17 h. La mère de Zoé note les indices sur chaque personne.","documents":[{"id":"indices","type":"tableau","titre":"Les indices","colonnes":["Suspect","Clue"],"lignes":[["Mia","Has chocolate on her fingers at 5.15 p.m."],["Jack","At football practice from 4 p.m. to 6 p.m."],["Olivia","Is on holiday in Spain this week"]],"enteteLignes":true,"source":"Tableau écrit pour l’exercice"}],"questions":[{"enonce":"Touche le suspect qui, d’après le tableau, **ne peut pas** avoir pris le gâteau à 17 h.","aide":"Compare l’heure du vol et l’emploi du temps de chacun.","type":"zone","document":"indices","multiple":false},{"enonce":"Complète les deux déductions.","aide":"Un suspect est écarté, l’autre est presque certain.","type":"trous","segments":["Jack ",0," have taken the cake. Mia ",1," have eaten it."],"banque":["must","can’t","mustn’t","to"]},{"enonce":"Quelle phrase veut dire « Olivia a peut-être pris le gâteau » ?","aide":"Cherche le modal de simple possibilité au passé.","type":"choix","options":[{"id":"a","texte":"Olivia can’t have taken the cake."},{"id":"b","texte":"Olivia should take the cake."},{"id":"c","texte":"Olivia may have taken the cake."},{"id":"d","texte":"Olivia must have taken the cake."}],"multiple":false},{"enonce":"Remets en ordre : « Mia est probablement la voleuse ». La phrase commence par Mia.","aide":"*Probably* se place après *be*.","type":"ordre","items":[{"id":"a","texte":"thief"},{"id":"b","texte":"is"},{"id":"c","texte":"the"},{"id":"d","texte":"probably"},{"id":"e","texte":"Mia"}]}]}$ex$::jsonb,
