  ('66a3ad58-1283-5ddb-a798-8120805cf7ad'::uuid, 3, 3, 15, 50, 5,
   $ex${"titre":"Le bus de huit heures","competence":"argumenter","situation":"Leo et Zoé attendent le bus du collège. Il est 8 h 15 et rien ne vient. Ils lisent aussi la météo du jour.","documents":[{"id":"meteo","type":"texte","genre":"article","titre":"Weather report","blocs":["The sky is grey this morning. It’s likely to rain after lunch. Temperatures should reach 17 degrees in the afternoon."],"source":"Bulletin écrit pour l’exercice"},{"id":"bus","type":"dialogue","modele":"sms","titre":"Messages de Leo et Zoé","participants":[{"nom":"Leo","emoji":"👦","cote":"gauche"},{"nom":"Zoé","emoji":"👧","cote":"droite"}],"repliques":[{"qui":"Leo","texte":"The bus isn’t here. It’s quarter past eight!"},{"qui":"Zoé","texte":"It must have left early. Or it might have broken down."},{"qui":"Leo","texte":"It can’t have left early. The driver always waits!"}],"source":"Messages écrits pour l’exercice"}],"questions":[{"enonce":"Touche les **deux mots** de l’expression qui dit qu’il va **probablement** pleuvoir.","aide":"Cherche un adjectif suivi de *to*.","type":"zone","document":"meteo","multiple":true},{"enonce":"Touche le modal de **forte probabilité** (les températures devraient atteindre 17 degrés).","aide":"Ce n’est pas *must*.","type":"zone","document":"meteo","multiple":false},{"enonce":"Touche le modal par lequel Leo dit que c’est **impossible**.","aide":"Il est à la forme négative.","type":"zone","document":"bus","multiple":false},{"enonce":"Que veut dire « It might have broken down » ?","aide":"*Might have* + participe passé : simple possibilité.","type":"choix","options":[{"id":"a","texte":"Il est peut-être tombé en panne"},{"id":"b","texte":"Il aurait dû tomber en panne"},{"id":"c","texte":"Il n’a pas pu tomber en panne"},{"id":"d","texte":"Il a dû tomber en panne"}],"multiple":false},{"enonce":"Associe chaque phrase à sa traduction.","aide":"Regarde le modal avant *have*.","type":"association","gauche":[{"id":"g0","texte":"He must have missed the train."},{"id":"g1","texte":"They can’t have arrived yet."},{"id":"g2","texte":"She may have forgotten."},{"id":"g3","texte":"You should have called."}],"droite":[{"id":"d0","texte":"Il a dû rater le train"},{"id":"d1","texte":"Elle a peut-être oublié"},{"id":"d2","texte":"Tu aurais dû appeler"},{"id":"d3","texte":"Ils ne peuvent pas être déjà arrivés"}]}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"zone","ids":["m7","m8"]},"explication":"**likely to** : *It’s likely to rain* = il va probablement pleuvoir."},{"cle":{"type":"zone","ids":["m13"]},"explication":"**should** exprime la forte probabilité."},{"cle":{"type":"zone","ids":["m20"]},"explication":"**can’t** : certitude négative (« c’est impossible »)."},{"cle":{"type":"choix","ids":["a"]},"explication":"**Il est peut-être tombé en panne** : might have + participe passé."},{"cle":{"type":"association","paires":{"g0":"d0","g2":"d1","g3":"d2","g1":"d3"}},"explication":"*Must have* : déduction. *Can’t have* : impossible. *May have* : peut-être. *Should have* : reproche."}]$ex$::jsonb),
  ('8f03755f-c4a4-5160-8f2c-0ed57d9ef1d7'::uuid, 1, 1, 5, 20, 3,
   $ex${"titre":"Dimanche au parc","competence":"comprendre-langue","situation":"Max raconte son dimanche dans son carnet. Certains verbes sont irréguliers, d’autres suivent la règle du -ed.","documents":[{"id":"carnet","type":"texte","genre":"recit","titre":"Max’s notebook","blocs":["Last Sunday, I got up late, ate pancakes and went to the park.","I played football and saw my cousin there. We bought ice cream and watched the ducks."],"source":"Texte écrit pour l’exercice"}],"questions":[{"enonce":"Touche les **cinq verbes irréguliers** au prétérit.","aide":"Les verbes réguliers se terminent par -ed.","type":"zone","document":"carnet","multiple":true},{"enonce":"Associe chaque verbe à son prétérit.","aide":"Pense à la deuxième colonne de la liste.","type":"association","gauche":[{"id":"g0","texte":"go"},{"id":"g1","texte":"see"},{"id":"g2","texte":"buy"},{"id":"g3","texte":"eat"}],"droite":[{"id":"d0","texte":"bought"},{"id":"d1","texte":"went"},{"id":"d2","texte":"ate"},{"id":"d3","texte":"saw"}]},{"enonce":"Complète après *didn’t*.","aide":"Après *did* ou *didn’t*, on emploie la base verbale.","type":"trous","segments":["I didn’t ",0," pancakes yesterday."],"banque":["ate","eating","eat","eaten"]}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"zone","ids":["m3","m6","m9","m17","m22"]},"explication":"**got, ate, went, saw, bought** sont irréguliers ; **played** et **watched** suivent la règle du -ed."},{"cle":{"type":"association","paires":{"g2":"d0","g0":"d1","g3":"d2","g1":"d3"}},"explication":"go – **went**, see – **saw**, buy – **bought**, eat – **ate**."},{"cle":{"type":"trous","trous":[["eat"]]},"affichage":"eat","explication":"**eat** : après **didn’t**, on emploie la **première colonne** (base verbale)."}]$ex$::jsonb),
  ('8f03755f-c4a4-5160-8f2c-0ed57d9ef1d7'::uuid, 2, 2, 10, 35, 4,
   $ex${"titre":"Le tableau des trois formes","competence":"lire-tableau","situation":"Pour réviser, Lena complète un tableau de verbes irréguliers. Il manque quelques formes.","documents":[{"id":"verbes","type":"tableau","titre":"Les trois formes","colonnes":["Base","Past","Past participle"],"lignes":[["write","wrote","?"],["drink","?","drunk"],["buy","bought","?"],["take","?","taken"],["speak","spoke","?"]],"enteteLignes":false,"source":"Tableau écrit pour l’exercice"}],"questions":[{"enonce":"Complète la case violette de la ligne **write** : le participe passé.","aide":"Pense à *I have …* devant le verbe.","type":"texte","placeholder":"Participe passé"},{"enonce":"Complète la case violette de la ligne **drink** : le prétérit.","aide":"Le prétérit est la deuxième colonne.","type":"texte","placeholder":"Prétérit"},{"enonce":"Complète avec les bonnes formes.","aide":"Après *has*, on emploie la troisième colonne.","type":"trous","segments":["Lena has ",0," a letter and she has ",1," a glass of water."],"banque":["written","drunk","wrote","drank"]},{"enonce":"Range chaque verbe selon sa famille.","aide":"Compare les trois colonnes : cut – cut – cut ; buy – bought – bought ; take – took – taken.","type":"categories","categories":[{"id":"c0","texte":"Trois formes identiques"},{"id":"c1","texte":"Prétérit = participe passé"},{"id":"c2","texte":"Trois formes différentes"}],"items":[{"id":"i0","texte":"put"},{"id":"i1","texte":"buy"},{"id":"i2","texte":"think"},{"id":"i3","texte":"write"},{"id":"i4","texte":"cut"},{"id":"i5","texte":"take"}]}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"texte","acceptes":["written"]},"affichage":"written","explication":"**written** : write – wrote – **written**."},{"cle":{"type":"texte","acceptes":["drank"]},"affichage":"drank","explication":"**drank** : drink – **drank** – drunk."},{"cle":{"type":"trous","trous":[["written"],["drunk"]]},"affichage":"written · drunk","explication":"Après **has**, on emploie le **participe passé** : *has written*, *has drunk*."},{"cle":{"type":"categories","items":{"i0":"c0","i1":"c1","i2":"c1","i3":"c2","i4":"c0","i5":"c2"}},"explication":"**cut, put** : trois formes identiques ; **buy, think** : prétérit = participe passé ; **take, write** : trois formes différentes."}]$ex$::jsonb),
  ('8f03755f-c4a4-5160-8f2c-0ed57d9ef1d7'::uuid, 3, 3, 15, 50, 5,
   $ex${"titre":"Une semaine en Cornouailles","competence":"argumenter","situation":"Ivy est en vacances en Cornouailles. Elle écrit à son grand-père, qui lui répond par message.","documents":[{"id":"lettre","type":"texte","genre":"lettre","titre":"Dear Grandpa","blocs":["Dear Grandpa, we have had a wonderful week in Cornwall. I have swum in the sea every day, and I have eaten fish and chips three times!","Yesterday we flew kites on the beach and Dad broke his sunglasses. I have written five postcards. Love, Ivy"],"source":"Lettre écrite pour l’exercice"},{"id":"sms","type":"dialogue","modele":"sms","titre":"Messages de Grand-père et Ivy","participants":[{"nom":"Grandpa","emoji":"👴","cote":"gauche"},{"nom":"Ivy","emoji":"👧","cote":"droite"}],"repliques":[{"qui":"Grandpa","texte":"Did you buy any stamps?"},{"qui":"Ivy","texte":"No, I didn’t buy any. The shop was closed."},{"qui":"Grandpa","texte":"Have you taken any photos?"},{"qui":"Ivy","texte":"Yes, I have taken fifty!"}],"source":"Messages écrits pour l’exercice"}],"questions":[{"enonce":"Touche les **deux verbes au prétérit** (hier).","aide":"Ils sont à la deuxième colonne de la liste.","type":"zone","document":"lettre","multiple":true},{"enonce":"Range chaque verbe de la lettre : **prétérit** (colonne 2) ou **participe passé** (colonne 3) ?","aide":"Les participes passés suivent *have* ou *has*.","type":"categories","categories":[{"id":"c0","texte":"Prétérit (colonne 2)"},{"id":"c1","texte":"Participe passé (colonne 3)"}],"items":[{"id":"i0","texte":"flew"},{"id":"i1","texte":"broke"},{"id":"i2","texte":"swum"},{"id":"i3","texte":"written"},{"id":"i4","texte":"eaten"}]},{"enonce":"Touche le verbe qui suit *didn’t* dans la réponse d’Ivy.","aide":"Après *didn’t*, on emploie la première colonne.","type":"zone","document":"sms","multiple":false},{"enonce":"Complète avec la bonne forme.","aide":"Après *has*, on emploie la troisième colonne.","type":"trous","segments":["Ivy has ",0," fifty photos."],"banque":["taking","take","took","taken"]},{"enonce":"Remets en ordre : « Je n’ai jamais vu la mer. » La phrase commence par I.","aide":"*never* se place entre l’auxiliaire et le participe passé.","type":"ordre","items":[{"id":"a","texte":"seen"},{"id":"b","texte":"the sea"},{"id":"c","texte":"have"},{"id":"d","texte":"I"},{"id":"e","texte":"never"}]}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"zone","ids":["m29","m36"]},"explication":"**flew** et **broke** sont au prétérit (colonne 2) : fly – flew – flown, break – broke – broken."},{"cle":{"type":"categories","items":{"i0":"c0","i1":"c0","i2":"c1","i3":"c1","i4":"c1"}},"explication":"**flew, broke** sont des prétérits ; **swum, eaten, written** suivent *have* : ce sont des participes passés."},{"cle":{"type":"zone","ids":["m8"]},"explication":"**buy** : après *didn’t*, on emploie la **base verbale**, pas *bought*."},{"cle":{"type":"trous","trous":[["taken"]]},"affichage":"taken","explication":"**taken** : *has taken*, avec le participe passé (take – took – taken)."},{"cle":{"type":"ordre","ids":["d","c","e","a","b"]},"explication":"**I have never seen the sea** : *see – saw – seen*, et *never* se place entre *have* et le participe."}]$ex$::jsonb),
  ('7c8bab04-3c5a-5039-9172-41360acb0e2b'::uuid, 1, 1, 5, 20, 3,
   $ex${"titre":"Les règles de la bibliothèque","competence":"comprendre-langue","situation":"Lina vient d’être inscrite à la bibliothèque de son collège. Elle lit l’affiche des règles avant d’emprunter son premier livre.","documents":[{"id":"regles","type":"fiche","modele":"affiche","entete":"School library rules","sousTitre":"Open every day","emoji":"📚","lignes":[{"texte":"You can borrow three books for two weeks.","id":"z1"},{"texte":"You can’t eat or drink in the library.","id":"z2"},{"texte":"Students may use the computers for homework.","id":"z3"},{"texte":"You mustn’t shout.","id":"z4"}],"pied":"Thank you!","teinte":"violet","source":"Affiche écrite pour l’exercice"}],"questions":[{"enonce":"Touche la règle qui dit que Lina **a le droit d’emprunter** des livres.","aide":"Cherche la phrase affirmative avec *borrow*.","type":"zone","document":"regles","multiple":false},{"enonce":"Que veut dire la règle « You can’t eat or drink in the library » ?","aide":"La forme négative de *can* refuse la permission.","type":"choix","options":[{"id":"a","texte":"Tu es capable de ne pas manger"},{"id":"b","texte":"Tu devrais éviter de boire"},{"id":"c","texte":"C’est interdit de manger ou de boire"},{"id":"d","texte":"Tu peux manger si tu veux"}],"multiple":false},{"enonce":"Range chaque demande selon son niveau de politesse.","aide":"*Can* est le plus courant, *may* le plus solennel.","type":"categories","categories":[{"id":"c0","texte":"Familier"},{"id":"c1","texte":"Poli"},{"id":"c2","texte":"Formel"}],"items":[{"id":"i0","texte":"Could I borrow your pen?"},{"id":"i1","texte":"Can I sit here?"},{"id":"i2","texte":"May I come in?"}]}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"zone","ids":["z1"]},"explication":"**You can borrow three books** : *can* accorde la permission, de façon courante."},{"cle":{"type":"choix","ids":["c"]},"explication":"**C’est interdit** : *can’t* exprime l’interdiction."},{"cle":{"type":"categories","items":{"i0":"c1","i1":"c0","i2":"c2"}},"explication":"**Can** est familier, **could** est poli, **may** est formel : plus on monte, plus on est respectueux."}]$ex$::jsonb),
  ('7c8bab04-3c5a-5039-9172-41360acb0e2b'::uuid, 2, 2, 10, 35, 4,
   $ex${"titre":"Un concert très surveillé","competence":"manier-langue","situation":"Eva raconte à son ami Ben le concert auquel elle est allée la semaine dernière. Ses parents lui ont fixé des règles.","documents":[{"id":"conv","type":"dialogue","modele":"sms","titre":"Messages d’Eva et Ben","participants":[{"nom":"Ben","emoji":"👦","cote":"gauche"},{"nom":"Eva","emoji":"👧","cote":"droite"}],"repliques":[{"qui":"Ben","texte":"Were you allowed to go to the concert last week?"},{"qui":"Eva","texte":"Yes, I was allowed to go! But I wasn’t allowed to stay late."},{"qui":"Ben","texte":"Lucky you! We will be allowed to go to the next one on our own."}],"source":"Messages écrits pour l’exercice"}],"questions":[{"enonce":"Touche le mot qui montre qu’Eva **n’avait pas** la permission de rester tard.","aide":"Cherche la forme négative de *was*.","type":"zone","document":"conv","multiple":false},{"enonce":"Complète avec la bonne forme de *be*.","aide":"*We* est un pluriel, et *last year* est au passé.","type":"trous","segments":["Last year, we ",0," allowed to wear our own clothes."],"banque":["were","are","be","was"]},{"enonce":"Hier, la prof a donné à Lola la permission de partir plus tôt. Quelle phrase est correcte ?","aide":"Pour une permission au passé, on ne garde pas *can* ni *may*.","type":"choix","options":[{"id":"a","texte":"I was allowed to leave early."},{"id":"b","texte":"I can leave early yesterday."},{"id":"c","texte":"I may leave early yesterday."},{"id":"d","texte":"I am allowed leave early yesterday."}],"multiple":false},{"enonce":"Remets en ordre : « Nous aurons le droit d’utiliser des téléphones ». La phrase commence par We.","aide":"Au futur : will + be allowed to.","type":"ordre","items":[{"id":"a","texte":"allowed"},{"id":"b","texte":"be"},{"id":"c","texte":"to"},{"id":"d","texte":"use"},{"id":"e","texte":"will"},{"id":"f","texte":"phones"},{"id":"g","texte":"We"}]}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"zone","ids":["m18"]},"explication":"**wasn’t** : *wasn’t allowed to* exprime la permission refusée au passé."},{"cle":{"type":"trous","trous":[["were"]]},"affichage":"were","explication":"**were** : *be allowed to* se met au prétérit (*we were allowed to*) pour parler d’une permission passée."},{"cle":{"type":"choix","ids":["a"]},"explication":"**I was allowed to leave early.** *Be allowed to* se conjugue à tous les temps."},{"cle":{"type":"ordre","ids":["g","e","b","a","c","d","f"]},"explication":"**We will be allowed to use phones** : will + be + allowed to + verbe."}]$ex$::jsonb),
  ('7c8bab04-3c5a-5039-9172-41360acb0e2b'::uuid, 3, 3, 15, 50, 5,
   $ex${"titre":"Les règles de l’auberge de jeunesse","competence":"argumenter","situation":"Lou passe quelques jours dans une auberge de jeunesse en Écosse. Il lit le règlement, puis envoie un message au gérant.","documents":[{"id":"reglement","type":"texte","genre":"article","titre":"House rules","blocs":["Guests may use the kitchen until 9 p.m. Visitors may not enter the bedrooms.","Last summer, guests were allowed to swim in the lake, but this year it is closed. You mustn’t light fires in the garden."],"source":"Règlement écrit pour l’exercice"},{"id":"sms","type":"dialogue","modele":"sms","titre":"Messages de Lou et du gérant","participants":[{"nom":"Lou","emoji":"🧑","cote":"gauche"},{"nom":"Gérant","emoji":"🧔","cote":"droite"}],"repliques":[{"qui":"Lou","texte":"Could I use the kitchen at 10 p.m.?"},{"qui":"Gérant","texte":"Sorry, you can’t. It closes at nine."}],"source":"Messages écrits pour l’exercice"}],"questions":[{"enonce":"Touche les **deux mots** qui forment le refus **formel** du règlement.","aide":"C’est le modal le plus poli, suivi de *not*.","type":"zone","document":"reglement","multiple":true},{"enonce":"Touche le mot par lequel le gérant **refuse** la demande de Lou.","aide":"Il refuse de façon courante, pas formelle.","type":"zone","document":"sms","multiple":false},{"enonce":"Lou voudrait cuisiner à 22 h. Que dit le règlement ?","aide":"Relis la première phrase du règlement.","type":"choix","options":[{"id":"a","texte":"Non : la cuisine ferme à 21 h"},{"id":"b","texte":"Non : les invités ne peuvent jamais cuisiner"},{"id":"c","texte":"Oui : tout est permis la nuit"},{"id":"d","texte":"Oui, avec un adulte"}],"multiple":false},{"enonce":"Complète pour dire que les clients avaient le droit de nager l’été dernier.","aide":"Il faut *be allowed to* au passé : le sujet est *guests*.","type":"trous","segments":["Last summer, guests ",0," ",1," to swim in the lake."],"banque":["was","allowed","allow","were"]},{"enonce":"Associe chaque phrase à sa fonction.","aide":"*Mustn’t* est plus fort que *can’t*.","type":"association","gauche":[{"id":"g0","texte":"You mustn’t light fires."},{"id":"g1","texte":"Visitors may not enter."},{"id":"g2","texte":"Could I use the kitchen?"},{"id":"g3","texte":"I was allowed to swim."}],"droite":[{"id":"d0","texte":"Refus formel d’un règlement"},{"id":"d1","texte":"Demande polie"},{"id":"d2","texte":"Permission au passé"},{"id":"d3","texte":"Interdiction forte"}]}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"zone","ids":["m10","m11"]},"explication":"**may not** : formule des règlements écrits, plus formelle que *can’t*."},{"cle":{"type":"zone","ids":["m11"]},"explication":"**can’t** : refus courant de la permission."},{"cle":{"type":"choix","ids":["a"]},"explication":"**La cuisine ferme à 21 h** : *Guests may use the kitchen until 9 p.m.*"},{"cle":{"type":"trous","trous":[["were"],["allowed"]]},"affichage":"were · allowed","explication":"**were allowed** : on conjugue *be* au prétérit, puis *allowed to*."},{"cle":{"type":"association","paires":{"g1":"d0","g2":"d1","g3":"d2","g0":"d3"}},"explication":"*Mustn’t* interdit fortement ; *may not* est la forme formelle des règlements ; *could* demande poliment ; *was allowed to* parle du passé."}]$ex$::jsonb),
  ('7a3cbe7a-fd30-543c-af21-3f6915fb1272'::uuid, 1, 1, 5, 20, 3,
   $ex${"titre":"La photo de classe","competence":"comprendre-langue","situation":"Une élève présente la photo de sa classe à une correspondante. Elle décrit les personnes et les lieux.","documents":[{"id":"photo","type":"texte","genre":"article","titre":"Our class photo","blocs":["Here is a photo of my class. The girl who is wearing a red hat is Mia. The boy whose bike is blue is Tom.","The place where we are standing is our school yard. The cake which Mia is holding is for our teacher."],"source":"Texte écrit pour l’exercice"}],"questions":[{"enonce":"Touche le pronom relatif qui reprend **une personne** (Mia).","aide":"Il commence par w et précède *is wearing*.","type":"zone","document":"photo","multiple":false},{"enonce":"Associe chaque pronom relatif à ce qu’il reprend.","aide":"Chaque pronom a son antécédent.","type":"association","gauche":[{"id":"g0","texte":"who"},{"id":"g1","texte":"which"},{"id":"g2","texte":"whose"},{"id":"g3","texte":"where"}],"droite":[{"id":"d0","texte":"une chose"},{"id":"d1","texte":"une personne"},{"id":"d2","texte":"la possession"},{"id":"d3","texte":"un lieu"}]},{"enonce":"Complète avec le bon pronom relatif.","aide":"Le père *de* cet ami : une possession.","type":"trous","segments":["I have a friend ",0," father is a pilot."],"banque":["whose","who","which","where"]}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"zone","ids":["m9"]},"explication":"**who** reprend une personne : *the girl who is wearing a red hat*."},{"cle":{"type":"association","paires":{"g1":"d0","g0":"d1","g2":"d2","g3":"d3"}},"explication":"**who** : personne ; **which** : chose ; **whose** : possession ; **where** : lieu."},{"cle":{"type":"trous","trous":[["whose"]]},"affichage":"whose","explication":"**whose** exprime la possession : *a friend whose father is a pilot*."}]$ex$::jsonb),
  ('7a3cbe7a-fd30-543c-af21-3f6915fb1272'::uuid, 2, 2, 10, 35, 4,
   $ex${"titre":"Mon prof de musique","competence":"manier-langue","situation":"Lou parle de son professeur de musique. Certaines relatives sont indispensables, d’autres ajoutent une information entre virgules.","documents":[{"id":"musique","type":"texte","genre":"article","titre":"My music teacher","blocs":["I love the film we saw yesterday. The teacher who teaches us music is great.","Mr Hill, who is also our coach, plays the guitar. The song that he played was my favourite."],"source":"Texte écrit pour l’exercice"}],"questions":[{"enonce":"Touche le pronom relatif de la phrase qui commence par **The teacher** : il est **indispensable** au sens (pas de virgules).","aide":"Cherche la relative qui n’est pas entre virgules.","type":"zone","document":"musique","multiple":false},{"enonce":"Range chaque phrase : relative **déterminative** ou **explicative** ?","aide":"L’explicative est entre virgules et on pourrait la supprimer.","type":"categories","categories":[{"id":"c0","texte":"Déterminative (indispensable)"},{"id":"c1","texte":"Explicative (entre virgules)"}],"items":[{"id":"i0","texte":"The song that he played was my favourite."},{"id":"i1","texte":"Mr Hill, who is also our coach, plays the guitar."},{"id":"i2","texte":"My cousin, who lives in Rome, is a pilot."},{"id":"i3","texte":"The teacher who teaches us music is great."}]},{"enonce":"Dans « The song that he played was my favourite », que peut-on faire ?","aide":"*That* est complément de *played* : le relatif peut sauter.","type":"choix","options":[{"id":"a","texte":"Remplacer *that* par *who*."},{"id":"b","texte":"Mettre *what* à la place de *that*."},{"id":"c","texte":"Supprimer *that* : the song he played."},{"id":"d","texte":"Ajouter des virgules autour de la relative."}],"multiple":false},{"enonce":"Complète avec le bon pronom relatif.","aide":"C’est une relative entre virgules, qui parle d’une personne.","type":"trous","segments":["My sister, ",0," lives in Rome, is a pilot."],"banque":["that","whose","which","who"]}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"zone","ids":["m9"]},"explication":"**who** (sans virgules) : la relative est **déterminative**, elle précise de quel professeur on parle."},{"cle":{"type":"categories","items":{"i0":"c0","i1":"c1","i2":"c1","i3":"c0"}},"explication":"**Déterminative** : sans virgules, indispensable. **Explicative** : entre virgules, information en plus."},{"cle":{"type":"choix","ids":["c"]},"explication":"*that* est **complément** dans une relative déterminative : il peut être **omis** (*the song he played*)."},{"cle":{"type":"trous","trous":[["who"]]},"affichage":"who","explication":"**who** : dans une relative explicative, on ne peut pas employer *that* ; pour une personne, c’est **who**."}]$ex$::jsonb),
  ('7a3cbe7a-fd30-543c-af21-3f6915fb1272'::uuid, 3, 3, 15, 50, 5,
   $ex${"titre":"Une lettre à la bibliothèque","competence":"argumenter","situation":"Lea écrit à un bibliothécaire, puis échange avec son ami Dan par message au sujet de la même visite.","documents":[{"id":"lettre","type":"texte","genre":"lettre","titre":"Dear Mr Evans","blocs":["Dear Mr Evans, I visited the library last Tuesday. The woman to whom I spoke was very kind.","The book that I wanted was already out, but the librarian, whose name was Mrs Carr, ordered it for me."],"source":"Lettre écrite pour l’exercice"},{"id":"sms","type":"dialogue","modele":"sms","titre":"Messages de Lea et Dan","participants":[{"nom":"Lea","emoji":"👧","cote":"gauche"},{"nom":"Dan","emoji":"👦","cote":"droite"}],"repliques":[{"qui":"Lea","texte":"I borrowed the book that you recommended."},{"qui":"Dan","texte":"Great! Is it the one you wanted?"},{"qui":"Lea","texte":"Yes. The library where I found it was closed, but the librarian, who knows me, opened it for me."}],"source":"Messages écrits pour l’exercice"}],"questions":[{"enonce":"Touche le pronom relatif qui exprime la **possession** (le nom de la bibliothécaire).","aide":"Il est entre virgules.","type":"zone","document":"lettre","multiple":false},{"enonce":"Comment dit-on, en anglais courant, « The woman to whom I spoke » ?","aide":"En anglais courant, la préposition passe à la fin de la relative.","type":"choix","options":[{"id":"a","texte":"The woman whom to I spoke."},{"id":"b","texte":"The woman to who I spoke."},{"id":"c","texte":"The woman which I spoke to."},{"id":"d","texte":"The woman who I spoke to."}],"multiple":false},{"enonce":"Dans les messages, range chaque groupe : le relatif **peut sauter** ou il est **obligatoire** ?","aide":"Le relatif est obligatoire quand il est le sujet de la relative.","type":"categories","categories":[{"id":"c0","texte":"Le relatif peut sauter"},{"id":"c1","texte":"Le relatif est obligatoire"}],"items":[{"id":"i0","texte":"the librarian who knows me"},{"id":"i1","texte":"the girl (who) I met"},{"id":"i2","texte":"the man who called"},{"id":"i3","texte":"the book (that) you recommended"}]},{"enonce":"Complète avec le bon pronom relatif.","aide":"Il reprend un lieu.","type":"trous","segments":["The library ",0," I found it was closed."],"banque":["whose","when","where","which"]},{"enonce":"Remets en ordre : « La fille à qui j’ai parlé était gentille. » La phrase commence par The girl.","aide":"La forme soutenue remonte la préposition avec le relatif.","type":"ordre","items":[{"id":"a","texte":"to whom"},{"id":"b","texte":"was kind"},{"id":"c","texte":"I"},{"id":"d","texte":"spoke"},{"id":"e","texte":"The girl"}]}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"zone","ids":["m29"]},"explication":"**whose** : *the librarian whose name was Mrs Carr*."},{"cle":{"type":"choix","ids":["d"]},"explication":"En anglais courant, la préposition se place **à la fin** : *the woman who I spoke to*."},{"cle":{"type":"categories","items":{"i0":"c1","i1":"c0","i2":"c1","i3":"c0"}},"explication":"Il peut sauter quand il est **complément** (*the book you recommended*) ; il est obligatoire quand il est **sujet** (*the librarian who knows me*)."},{"cle":{"type":"trous","trous":[["where"]]},"affichage":"where","explication":"**where** reprend un lieu : *the library where I found it*."},{"cle":{"type":"ordre","ids":["e","a","c","d","b"]},"explication":"**The girl to whom I spoke was kind** : en anglais soutenu, la préposition précède *whom*."}]$ex$::jsonb),
