   $ex${"titre":"Prêt pour le départ ?","competence":"comprendre-langue","situation":"Léo part en voyage scolaire demain. Sa mère lui envoie des messages pour vérifier qu’il est prêt.","documents":[{"id":"sms","type":"dialogue","modele":"sms","titre":"Messages de Maman et Léo","participants":[{"nom":"Mum","emoji":"👩","cote":"gauche"},{"nom":"Leo","emoji":"👦","cote":"droite"}],"repliques":[{"qui":"Mum","texte":"Have you packed your bag yet?"},{"qui":"Leo","texte":"Yes, I’ve already packed it. I’ve just finished my homework, but I haven’t found my passport."},{"qui":"Mum","texte":"Have you looked in the drawer?"},{"qui":"Leo","texte":"Not yet!"}],"source":"Messages écrits pour l’exercice"}],"questions":[{"enonce":"Touche les **deux marqueurs** placés entre *have* et le participe passé dans la réponse de Léo.","aide":"Un marqueur de temps se glisse entre l’auxiliaire et le participe.","type":"zone","document":"sms","multiple":true},{"enonce":"Complète avec l’auxiliaire qui convient.","aide":"Léo est une troisième personne du singulier.","type":"trous","segments":["Leo ",0," already packed his bag."],"banque":["have","has","is","did"]},{"enonce":"Léo a-t-il retrouvé son passeport ?","aide":"Cherche la phrase négative de Léo.","type":"choix","options":[{"id":"a","texte":"On ne sait rien : il n’en parle pas."},{"id":"b","texte":"Non, il ne l’a pas encore retrouvé."},{"id":"c","texte":"Oui, il l’a retrouvé ce matin."},{"id":"d","texte":"Oui, il l’a retrouvé dans le tiroir."}],"multiple":false}]}$ex$::jsonb,
