  ('7688a5e0-4936-5086-bec6-04c00a816ead'::uuid, 2, 2, 10, 35, 4,
   $ex${"titre":"Depuis quand, pendant combien de temps ?","competence":"manier-langue","situation":"Le club de loisirs du collège présente ses membres. Chacun dit depuis combien de temps il pratique son activité.","documents":[{"id":"club","type":"tableau","titre":"Les membres du club","colonnes":["Member","Activity","Since / for"],"lignes":[["Amy","play the piano","for four years"],["Ravi","study French","since September"],["Lena","live in Dover","since she was six"],["Sam","have a dog","for two months"]],"enteteLignes":false,"source":"Informations écrites pour l’exercice"}],"questions":[{"enonce":"Touche les **deux cases** qui donnent une **durée** (une quantité de temps).","aide":"Une durée répond à « pendant combien de temps ? ».","type":"zone","document":"club","multiple":true},{"enonce":"Complète avec **since** ou **for**.","aide":"Septembre est un point de départ ; deux mois est une durée.","type":"trous","segments":["Ravi has studied French ",0," September, and Sam has had his dog ",1," two months."],"banque":["for","in","ago","since"]},{"enonce":"Quelle phrase est correcte ?","aide":"Il faut un point de départ après *since*, et le present perfect.","type":"choix","options":[{"id":"a","texte":"Lena has lived in Dover for she was six."},{"id":"b","texte":"Lena has lived in Dover since she was six."},{"id":"c","texte":"Lena has lived in Dover since six years."},{"id":"d","texte":"Lena lives in Dover since she was six."}],"multiple":false},{"enonce":"Range chaque expression : **for** ou **since** ?","aide":"For : combien de temps. Since : à partir de quand.","type":"categories","categories":[{"id":"c0","texte":"for"},{"id":"c1","texte":"since"}],"items":[{"id":"i0","texte":"two hours"},{"id":"i1","texte":"2020"},{"id":"i2","texte":"I was ten"},{"id":"i3","texte":"Monday"},{"id":"i4","texte":"three weeks"},{"id":"i5","texte":"a long time"}]}]}$ex$::jsonb,
