  ('7688a5e0-4936-5086-bec6-04c00a816ead'::uuid, 3, 3, 15, 50, 5,
   $ex${"titre":"Une lettre du Japon","competence":"argumenter","situation":"Emily voyage à Tokyo avec sa famille. Elle écrit à sa grand-mère, qui lui répond ensuite par message.","documents":[{"id":"lettre","type":"texte","genre":"lettre","titre":"Dear Gran","blocs":["Dear Gran, we arrived in Tokyo on Monday, so we have been here for four days. I have already tried sushi!","Yesterday we visited a big castle. I have never seen such a huge city before. Love, Emily"],"source":"Lettre écrite pour l’exercice"},{"id":"sms","type":"dialogue","modele":"sms","titre":"Messages de Gran et Emily","participants":[{"nom":"Gran","emoji":"👵","cote":"gauche"},{"nom":"Emily","emoji":"👧","cote":"droite"}],"repliques":[{"qui":"Gran","texte":"Have you visited Kyoto yet?"},{"qui":"Emily","texte":"No, I have never been there. We are going next week!"}],"source":"Messages écrits pour l’exercice"}],"questions":[{"enonce":"Touche les **deux verbes au prétérit** : ils sont accompagnés d’un repère de date précis.","aide":"Cherche *on Monday* et *yesterday*.","type":"zone","document":"lettre","multiple":true},{"enonce":"Pourquoi Emily écrit-elle « we visited a castle yesterday » et non « we have visited a castle yesterday » ?","aide":"Quel mot situe l’action à une date précise ?","type":"choix","options":[{"id":"a","texte":"Parce que *yesterday* est un repère passé précis."},{"id":"b","texte":"Parce que le château est loin d’elle maintenant."},{"id":"c","texte":"Parce que le present perfect est réservé aux verbes irréguliers."},{"id":"d","texte":"Parce que *visit* ne se met jamais au present perfect."}],"multiple":false},{"enonce":"Range chaque phrase : **present perfect** ou **prétérit** ?","aide":"Une date précise appelle le prétérit.","type":"categories","categories":[{"id":"c0","texte":"Present perfect"},{"id":"c1","texte":"Prétérit"}],"items":[{"id":"i0","texte":"I’ve never been to Kyoto."},{"id":"i1","texte":"We went there yesterday."},{"id":"i2","texte":"We have been here for four days."},{"id":"i3","texte":"She saw it last week."},{"id":"i4","texte":"I have tried sushi."},{"id":"i5","texte":"We arrived on Monday."}]},{"enonce":"Remets en ordre : « Elle est à Tokyo depuis lundi. » La phrase commence par She.","aide":"Commence par have / has + participe passé.","type":"ordre","items":[{"id":"a","texte":"Monday"},{"id":"b","texte":"been"},{"id":"c","texte":"since"},{"id":"d","texte":"in Tokyo"},{"id":"e","texte":"She"},{"id":"f","texte":"has"}]},{"enonce":"Dans les messages, touche le marqueur d’**expérience** qui veut dire « jamais ».","aide":"Il se place entre have et le participe passé.","type":"zone","document":"sms","multiple":false}]}$ex$::jsonb,
