l de la main qui compte ici.","type":"choix","options":[{"id":"a","texte":"La qualité de fabrication de l’objet"},{"id":"b","texte":"Le choix de l’objet et son déplacement"},{"id":"c","texte":"Le prix payé par l’artiste"},{"id":"d","texte":"La beauté de l’objet"}],"multiple":false}]}$ex$::jsonb,
